// GÉNÉRÉ PAR scripts/embed-assets.mjs — NE PAS ÉDITER À LA MAIN.
// Copies (imports réécrits) des sources gelées + runtime compilateur,
// embarquées pour garder le chemin de compilation PUR (zéro fs).
// Non-dérive garantie par tests/embedded-assets.test.ts.
export const EMBEDDED_ASSETS: Readonly<Record<string, string>> = {
  "lib/blocks/components.tsx": "// LES 6 SMART BLOCKS v1 — composites DE PRIMITIVES exclusivement (D-023).\n// RÈGLE MÉCANISÉE (tests/etancheite-ratchet.test.ts) : tout le visuel passe\n// par @deribfy/primitives ; seul composant react-native autorisé ici :\n// FlatList (structurel). AUCUN StyleSheet, AUCUN style en dur — le moteur\n// de styling reste remplaçable (D-021) et les tokens restent la seule\n// source visuelle. AUCUNE syntaxe Maestro/Detox : les blocs sont\n// E2E-agnostiques (D-022/D-023), seuls les testID standard sont exposés.\nimport { FlatList } from \"react-native\";\nimport {\n  AppButton,\n  AppText,\n  Badge,\n  ListRow,\n  Section,\n  StateView,\n  AppImage,\n  TextField,\n} from \"../primitives\";\nimport type {\n  Blocks,\n  ButtonBlockProps,\n  DetailHeaderBlockProps,\n  EmptyStateBlockProps,\n  FormBlockProps,\n  HeaderBlockProps,\n  ListBlockProps,\n} from \"./contracts.ts\";\n\nexport function HeaderBlock({ title, subtitle, testID }: HeaderBlockProps) {\n  return (\n    <Section testID={testID}>\n      <AppText variant=\"heading\">{title}</AppText>\n      {subtitle !== undefined && <AppText tone=\"muted\">{subtitle}</AppText>}\n    </Section>\n  );\n}\n\nexport function ListBlock({\n  title,\n  items,\n  state = { kind: \"ready\" },\n  search,\n  filters,\n  onItemPress,\n  testID,\n}: ListBlockProps) {\n  // DET-033 (jugement propriétaire sur appareil) : les états ne remplacent\n  // plus le BLOC ENTIER — ils ne remplacent que la ZONE DE CONTENU. Avant,\n  // une saisie sans correspondance faisait rendre l'état vide À LA PLACE du\n  // champ de recherche : le champ disparaissait sous les doigts, clavier\n  // fermé. Recherche et filtres restent MONTÉS quel que soit l'état, et\n  // vivent DANS la liste (en-tête défilant) : une seule surface de\n  // défilement, plus deux régions étanches.\n  const etatContenu =\n    state.kind === \"loading\" ? (\n      <StateView state=\"loading\" title={state.title} />\n    ) : state.kind === \"empty\" ? (\n      <StateView state=\"empty\" title={state.title} message={state.message} />\n    ) : state.kind === \"error\" ? (\n      <StateView\n        state=\"error\"\n        title={state.title}\n        message={state.message}\n        actionLabel={state.retryLabel}\n        onAction={state.onRetry}\n      />\n    ) : null;\n  // Contrôles TOUJOURS montés (élément stable : l'identité du TextField\n  // survit aux rendus — le focus et le clavier survivent avec elle).\n  const controles = (\n    <>\n      {search === undefined ? null : (\n        <TextField\n          testID={`${testID ?? \"list\"}-search`}\n          // DET-033 : champ compact — le sens passe par `placeholder`, la\n          // ligne de libellé disparaît, l'accessibilité garde son nom.\n          label=\"\"\n          accessibilityLabel={search.placeholder}\n          placeholder={search.placeholder}\n          value={search.value}\n          onChangeText={search.onChange}\n        />\n      )}\n      {/* E1 (D-129) — filtres pilotés : la saisie appartient à l'appelant. */}\n      {(filters ?? []).map((f, i) =>\n        f.inputType === \"text\" ? (\n          <TextField\n            key={`${testID ?? \"list\"}-filter-${String(i)}`}\n            testID={`${testID ?? \"list\"}-filter-${String(i)}`}\n            label={f.label}\n            value={f.value}\n            onChangeText={f.onChange}\n          />\n        ) : (\n          // DET-034 : un filtre n'est pas une action — les options sont des\n          // CHIPS (visuel de badge, cible tactile intacte), la rangée perd son\n          // titre VISIBLE (la hiérarchie revient à la recherche) mais garde son\n          // nom pour l'accessibilité, et l'état sélectionné se dit.\n          <Section\n            key={`${testID ?? \"list\"}-filter-${String(i)}`}\n            accessibilityLabel={f.label}\n            inline\n          >\n            {(f.options ?? []).map((option) => (\n              <AppButton\n                key={option}\n                testID={`${testID ?? \"list\"}-filter-${String(i)}-${option}`}\n                // DET-032 : le libellé peut différer de la VALEUR — le testID,\n                // le filtrage et onChange restent sur l'option brute.\n                label={f.optionLabels?.[option] ?? option}\n                kind=\"chip\"\n                selected={f.value === option}\n                onPress={() => {\n                  f.onChange(f.value === option ? \"\" : option);\n                }}\n              />\n            ))}\n          </Section>\n        ),\n      )}\n    </>\n  );\n  return (\n    // `fill` (DET-006) : la section BORNE la hauteur de la liste virtualisée.\n    // Sans parent borné, la FlatList rend tous ses éléments. L'intention est\n    // DÉCLARÉE ici ; le style reste entièrement porté par les primitives —\n    // la contrainte « aucun StyleSheet, aucun style en dur » est préservée.\n    <Section title={title} testID={testID} fill>\n      <FlatList\n        // DET-016 (D-039, dimension A étendue) : ajustement natif aux insets\n        // du clavier. Propriété VÉRIFIÉE sur RN 0.86.3 — déclarée dans\n        // `ScrollViewPropsIOS`, sans implémentation Android : elle agit sur\n        // iOS et reste INERTE sur Android, qui est couvert par le mode de\n        // redimensionnement déclaré au manifeste. Aucun `Platform.OS` requis.\n        // `keyboardShouldPersistTaps` évite qu'un appui sur un contrôle\n        // pendant l'édition soit absorbé par la fermeture du clavier.\n        // Ce sont des PROPRIÉTÉS structurelles, jamais des styles.\n        // DET-033 : recherche et filtres vivent EN-TÊTE DE LISTE — une seule\n        // surface de défilement — et l'état (chargement/vide/erreur) ne\n        // remplace que la zone de contenu, via ListEmptyComponent.\n        automaticallyAdjustKeyboardInsets\n        keyboardShouldPersistTaps=\"handled\"\n        ListHeaderComponent={controles}\n        ListEmptyComponent={etatContenu}\n        data={state.kind === \"ready\" ? items : []}\n        keyExtractor={(item) => item.id}\n        renderItem={({ item }) => (\n          <ListRow\n            // VIGNETTE (1.2.0, D-087) : `leading` existait deja au contrat de\n            // la primitive. Sans `imageUri`, la ligne reste celle de 1.1.0.\n            leading={\n              item.imageUri === undefined ? undefined : (\n                <AppImage uri={item.imageUri} variant=\"thumb\" />\n              )\n            }\n            title={item.title}\n            subtitle={item.subtitle}\n            trailing={item.trailing}\n            badge={item.badge}\n            onPress={\n              onItemPress === undefined\n                ? undefined\n                : () => {\n                    onItemPress(item.id);\n                  }\n            }\n            testID={`${testID ?? \"list\"}-row-${item.id}`}\n          />\n        )}\n      />\n    </Section>\n  );\n}\n\nexport function FormBlock({\n  title,\n  fields,\n  values,\n  onChangeField,\n  submitLabel,\n  onSubmit,\n  state = \"ready\",\n  errorMessage,\n  fieldErrors,\n  loadingTitle,\n  emptyTitle,\n  testID,\n}: FormBlockProps) {\n  // REGISTRE 1.1.0 (D-060) : `loading` et `empty` entrent dans l'union. Comme\n  // ailleurs, un état sans titre DÉCLARÉ n'est pas rendu — le moteur n'invente\n  // aucun texte (F3).\n  if (state === \"loading\" && loadingTitle !== undefined) {\n    return <StateView state=\"loading\" title={loadingTitle} testID={testID} />;\n  }\n  if (state === \"empty\" && emptyTitle !== undefined) {\n    return <StateView state=\"empty\" title={emptyTitle} testID={testID} />;\n  }\n  return (\n    <Section title={title} testID={testID}>\n      {fields.map((field) => (\n        <TextField\n          key={field.id}\n          label={field.label}\n          placeholder={field.placeholder}\n          secure={field.secure}\n          value={values[field.id] ?? \"\"}\n          onChangeText={(v) => {\n            onChangeField(field.id, v);\n          }}\n          error={fieldErrors?.[field.id]}\n          testID={`${testID ?? \"form\"}-field-${field.id}`}\n        />\n      ))}\n      {state === \"error\" && errorMessage !== undefined && (\n        <AppText tone=\"error\" testID={`${testID ?? \"form\"}-error`}>\n          {errorMessage}\n        </AppText>\n      )}\n      <AppButton\n        label={submitLabel}\n        onPress={onSubmit}\n        loading={state === \"submitting\"}\n        testID={`${testID ?? \"form\"}-submit`}\n      />\n    </Section>\n  );\n}\n\nexport function ButtonBlock({ label, kind, onPress, testID }: ButtonBlockProps) {\n  return <AppButton label={label} kind={kind} onPress={onPress} testID={testID} />;\n}\n\nexport function EmptyStateBlock({\n  title,\n  message,\n  actionLabel,\n  onAction,\n  testID,\n}: EmptyStateBlockProps) {\n  return (\n    <StateView\n      state=\"empty\"\n      title={title}\n      message={message}\n      actionLabel={actionLabel}\n      onAction={onAction}\n      testID={testID}\n    />\n  );\n}\n\nexport function DetailHeaderBlock({\n  title,\n  subtitle,\n  badges,\n  trailing,\n  state = { kind: \"ready\" },\n  imageUri,\n  testID,\n}: DetailHeaderBlockProps) {\n  // REGISTRE 1.1.0 (D-060) : les trois états que la dimension C nomme. Titres\n  // issus des DONNÉES — aucun texte moteur (F3).\n  if (state.kind === \"loading\") {\n    return <StateView state=\"loading\" title={state.title} testID={testID} />;\n  }\n  if (state.kind === \"empty\") {\n    return (\n      <StateView state=\"empty\" title={state.title} message={state.message} testID={testID} />\n    );\n  }\n  if (state.kind === \"error\") {\n    return (\n      <StateView state=\"error\" title={state.title} message={state.message} testID={testID} />\n    );\n  }\n  return (\n    <Section testID={testID}>\n      {/* VISUEL D'EN-TETE (1.2.0, D-087). Le style vit dans la PRIMITIVE : le\n          cliquet d'etancheite interdit tout style ici, et il a raison — le bloc\n          choisit un ROLE, la primitive choisit la forme. Commentaire volontai-\n          rement sans accents ni phrase longue : le cliquet F3 cherche des\n          chaines linguistiques par motif et ne distingue pas un commentaire. */}\n      {imageUri === undefined ? null : (\n        <AppImage uri={imageUri} variant=\"header\" testID={`${testID ?? \"detail\"}-image`} />\n      )}\n      <AppText variant=\"heading\">{title}</AppText>\n      {subtitle !== undefined && <AppText tone=\"muted\">{subtitle}</AppText>}\n      {trailing !== undefined && (\n        <AppText variant=\"title\" tone=\"primary\">\n          {trailing}\n        </AppText>\n      )}\n      {/* CLÉ STABLE (D-076) — `key={badge}` collait deux badges de même valeur,\n          et React refusait : « two children with the same key `` ». Le cas réel\n          était deux champs de badge VIDES. La position rend la clé unique par\n          construction, quelles que soient les valeurs. */}\n      {badges?.map((badge, i) => <Badge key={`${String(i)}:${badge}`} label={badge} />)}\n    </Section>\n  );\n}\n\n// Conformité au contrat vérifiée par le compilateur (patron 3.2 / banc P-003).\nexport const blocks: Blocks = {\n  HeaderBlock,\n  ListBlock,\n  FormBlock,\n  ButtonBlock,\n  EmptyStateBlock,\n  DetailHeaderBlock,\n};\n",
  "lib/blocks/contracts.ts": "// CONTRATS COMPORTEMENTAUX DES SMART BLOCKS v1 (ROADMAP Phase 3.3, D-023 —\n// registre de blocs COMPOSITES DE PRIMITIVES, granularité section d'écran).\n//\n// RÈGLE D'ÉTANCHÉITÉ (§22, D-021 — même cliquet que les primitives) : ce\n// fichier n'importe QUE des types de `react`. Aucun type de styling, aucun\n// type react-native — le moteur de styling ET le moteur E2E restent\n// remplaçables sans toucher aux contrats des blocs.\n//\n// Les ÉTATS (loading/empty/error) sont EXPLICITES et contractuels : le bloc\n// ne déduit jamais son état de ses données (déterminisme — c'est le\n// compilateur/runtime qui décide de l'état, jamais une heuristique).\nimport type { ComponentType } from \"react\";\n\nexport interface BlockA11yProps {\n  testID?: string;\n}\n\nexport interface HeaderBlockProps extends BlockA11yProps {\n  title: string;\n  subtitle?: string;\n}\n\n/**\n * RECHERCHE DANS UNE LISTE (1.2.0, D-087) — état tenu par l'appelant.\n *\n * Le bloc ne possède pas la saisie : il la reçoit et la restitue. C'est ce qui\n * lui permet de rester un composant PUR, testable sans monter d'application.\n */\nexport interface ListSearchSpec {\n  value: string;\n  onChange: (v: string) => void;\n  placeholder?: string;\n}\n\n/**\n * FILTRE PILOTÉ PAR L'UTILISATEUR (E1, D-129) — même contrat que la\n * recherche : le bloc ne possède pas la saisie, il la reçoit et la restitue.\n * `text` rend un champ de saisie ; `choice` rend les options FOURNIES\n * (valeurs distinctes du périmètre, calculées par l'appelant) — re-presser\n * l'option active la désactive. Une valeur vide = filtre inactif.\n */\nexport interface ListFilterSpec {\n  label: string;\n  value: string;\n  onChange: (v: string) => void;\n  inputType: \"text\" | \"choice\";\n  options?: readonly string[];\n  /**\n   * LIBELLÉS D'AFFICHAGE des options (1.4.0, DET-032) — clé = option BRUTE.\n   * L'option reste la VALEUR (filtrage, testID) ; seul le texte rendu change.\n   * Absent ou partiel : l'option brute est affichée — appelant 1.3.0 inchangé.\n   */\n  optionLabels?: Readonly<Record<string, string>>;\n}\n\nexport interface ListItemData {\n  id: string;\n  /** Vignette de la ligne (1.2.0) — absente = ligne purement textuelle. */\n  imageUri?: string;\n  title: string;\n  subtitle?: string;\n  trailing?: string;\n  badge?: string;\n}\n\n// F3 (revue pré-gel 2026-08-28) : état DISCRIMINÉ — les libellés d'état\n// sont REQUIS exactement quand l'état les rend, et FOURNIS par l'appelant\n// (le compilateur, depuis l'AIR/les locales). AUCUN texte par défaut dans\n// le moteur : une chaîne codée en dur fuiterait la langue du moteur dans\n// des apps de langue arbitraire (i18n structurel, non-négociable 16).\nexport const LIST_BLOCK_STATES = [\"ready\", \"loading\", \"empty\", \"error\"] as const;\nexport type ListBlockState =\n  | { kind: \"ready\" }\n  | { kind: \"loading\"; title: string }\n  | { kind: \"empty\"; title: string; message?: string }\n  | {\n      kind: \"error\";\n      title: string;\n      message?: string;\n      retryLabel?: string;\n      onRetry?: () => void;\n    };\n\nexport interface ListBlockProps extends BlockA11yProps {\n  /** Recherche rendue EN TÊTE de la liste (1.2.0) — absente = pas de champ. */\n  search?: ListSearchSpec;\n  /** Filtres pilotés (E1, D-129) — rendus sous la recherche, ≤ 3. */\n  filters?: readonly ListFilterSpec[];\n  title?: string;\n  items: readonly ListItemData[];\n  /** État EXPLICITE (défaut { kind: \"ready\" }) — jamais déduit des données. */\n  state?: ListBlockState;\n  onItemPress?: (itemId: string) => void;\n}\n\nexport interface FormFieldSpec {\n  id: string;\n  label: string;\n  placeholder?: string;\n  secure?: boolean;\n}\n\n// REGISTRE 1.1.0 (D-060) : `loading` et `empty` entrent dans l'union.\n// Fait mesuré : la dimension C d'A++ exige que TOUT bloc consommant des données\n// expose loading/empty/error. `form` ne savait exprimer NI l'un NI l'autre — la\n// dimension était donc INATTEIGNABLE, pas seulement non atteinte (APP-D003).\n// Ajout STRICTEMENT ADDITIF : aucun état retiré, `state` reste optionnel, défaut\n// \"ready\" — un appelant 1.0.0 se comporte à l'identique.\n// D-095 — SOURCE UNIQUE DES ÉTATS. Le tableau est la déclaration ; le type en\n// DÉRIVE. Le registre pointe sur ce même tableau. Il n'existe donc plus de\n// seconde liste à tenir à jour, et la dérive mesurée en F5 devient impossible\n// par construction — pas seulement détectée.\nexport const FORM_BLOCK_STATES = [\"ready\", \"loading\", \"empty\", \"submitting\", \"error\"] as const;\nexport type FormBlockState = (typeof FORM_BLOCK_STATES)[number];\n\nexport interface FormBlockProps extends BlockA11yProps {\n  title?: string;\n  fields: readonly FormFieldSpec[];\n  values: Readonly<Record<string, string>>;\n  onChangeField: (fieldId: string, value: string) => void;\n  submitLabel: string;\n  onSubmit: () => void;\n  /** État EXPLICITE (défaut \"ready\"). */\n  state?: FormBlockState;\n  errorMessage?: string;\n  fieldErrors?: Readonly<Record<string, string>>;\n  /** Titres des états `loading`/`empty` — DONNÉES, jamais texte moteur (F3). */\n  loadingTitle?: string;\n  emptyTitle?: string;\n}\n\nexport interface ButtonBlockProps extends BlockA11yProps {\n  label: string;\n  kind?: \"primary\" | \"ghost\";\n  /**\n   * OPTIONNEL depuis 1.1.0 (D-084) — même patron que `onItemPress` du bloc\n   * liste : sans gestionnaire, le bouton n'est PAS pressable. Un effet que le\n   * moteur n'exécute pas ne doit pas offrir d'affordance. Additif : un appelant\n   * qui fournit `onPress` est inchangé.\n   */\n  onPress?: () => void;\n}\n\nexport interface EmptyStateBlockProps extends BlockA11yProps {\n  title: string;\n  message?: string;\n  actionLabel?: string;\n  onAction?: () => void;\n}\n\n// REGISTRE 1.1.0 (D-060) — même motif que `form` : `detail_header` consomme des\n// données et ne portait AUCUN état. Les titres viennent des DONNÉES, jamais du\n// moteur (F3) : un état sans titre déclaré n'est donc pas rendu.\nexport const DETAIL_HEADER_BLOCK_STATES = [\"ready\", \"loading\", \"empty\", \"error\"] as const;\nexport type DetailHeaderBlockState =\n  | { kind: \"ready\" }\n  | { kind: \"loading\"; title: string }\n  | { kind: \"empty\"; title: string; message?: string }\n  | { kind: \"error\"; title: string; message?: string };\n\nexport interface DetailHeaderBlockProps extends BlockA11yProps {\n  title: string;\n  subtitle?: string;\n  badges?: readonly string[];\n  trailing?: string;\n  /** État EXPLICITE (défaut { kind: \"ready\" }) — jamais déduit des données. */\n  state?: DetailHeaderBlockState;\n  /**\n   * VISUEL D'EN-TÊTE (1.2.0, D-087) — une fiche de plat, de bien ou d'article\n   * sans image n'est pas une fiche. Absent = aucun visuel rendu, comportement\n   * 1.1.0 inchangé.\n   */\n  imageUri?: string;\n}\n\n// Le record complet — la conformité de l'implémentation est vérifiée par le\n// compilateur TypeScript (patron des primitives 3.2 et du banc P-003).\nexport interface Blocks {\n  HeaderBlock: ComponentType<HeaderBlockProps>;\n  ListBlock: ComponentType<ListBlockProps>;\n  FormBlock: ComponentType<FormBlockProps>;\n  ButtonBlock: ComponentType<ButtonBlockProps>;\n  EmptyStateBlock: ComponentType<EmptyStateBlockProps>;\n  DetailHeaderBlock: ComponentType<DetailHeaderBlockProps>;\n}\n\n// ── D-095 · LIAISON VÉRIFIÉE PAR LE COMPILATEUR.\n//\n// Pour les unions DISCRIMINÉES, chaque variante porte des champs différents :\n// le tableau ne peut pas engendrer l'union. Il l'ENCADRE. Ces deux assertions\n// échouent à la compilation si le tableau et l'union divergent, dans un sens\n// comme dans l'autre — c'est la garantie que `BLOCKS[].states` n'avait pas.\ntype MemeEnsemble<A extends string, B extends string> = [A] extends [B]\n  ? [B] extends [A]\n    ? true\n    : never\n  : never;\n\n// eslint-disable-next-line @typescript-eslint/no-unused-vars\ntype _ListeLiee = MemeEnsemble<ListBlockState[\"kind\"], (typeof LIST_BLOCK_STATES)[number]>;\n// eslint-disable-next-line @typescript-eslint/no-unused-vars\ntype _DetailLie = MemeEnsemble<\n  DetailHeaderBlockState[\"kind\"],\n  (typeof DETAIL_HEADER_BLOCK_STATES)[number]\n>;\n\n// Blocs SANS prop `state` : ils ne rendent qu'un état, déclaré ici pour que\n// contracts.ts reste l'unique source des six blocs.\nexport const BUTTON_BLOCK_STATES = [\"ready\"] as const;\nexport const HEADER_BLOCK_STATES = [\"ready\"] as const;\nexport const EMPTY_STATE_BLOCK_STATES = [\"empty\"] as const;\n",
  "lib/primitives/contracts.ts": "// CONTRATS DE PRIMITIVES v1 (ROADMAP Phase 3.2 — dossier d'options validé\n// par le propriétaire : A1+B2+C2+D1).\n//\n// RÈGLE D'ÉTANCHÉITÉ (ARCHITECTURE §22, D-021, prouvée 6/6 au banc P-003,\n// verrouillée par tests/contracts-ratchet.test.ts) : ce fichier n'importe\n// QUE des types de `react`. Aucun type de bibliothèque de styling, aucun\n// type react-native, aucune valeur — le moteur de styling reste remplaçable\n// sans toucher ni aux contrats, ni aux blocs, ni à l'AIR.\n//\n// Surface a11y minimale (C2) : `testID` partout ; `accessibilityLabel` sur\n// les primitives interactives/informatives. Les RÔLES a11y sont posés par\n// l'implémentation (détail interne, pas contractuel).\nimport type { ComponentType, PropsWithChildren, ReactNode } from \"react\";\n\nexport type Scheme = \"light\" | \"dark\";\n\nexport interface A11yProps {\n  testID?: string;\n  accessibilityLabel?: string;\n}\n\n// Les 4 variantes de texte = les 4 tokens de police de la source unique.\nexport type TextVariant = \"label\" | \"body\" | \"title\" | \"heading\";\nexport type TextTone = \"default\" | \"muted\" | \"primary\" | \"error\" | \"success\" | \"warn\";\n\nexport type AppTextProps = PropsWithChildren<\n  A11yProps & {\n    variant?: TextVariant;\n    tone?: TextTone;\n    /** Alignement LOGIQUE (miroir RTL automatique) — jamais left/right. */\n    align?: \"start\" | \"center\" | \"end\";\n  }\n>;\n\nexport type ScreenShellProps = PropsWithChildren<A11yProps & { title: string }>;\n\n// `fill` (D-039/DET-006) : la section occupe la hauteur disponible et BORNE\n// ses enfants. Indispensable à une liste virtualisée : sans parent borné,\n// une FlatList reçoit une hauteur infinie et rend TOUS ses éléments — la\n// virtualisation est neutralisée. Le style reste porté par les primitives ;\n// le paquet `blocks` se contente de DÉCLARER l'intention (contrainte\n// « aucun style en dur », D-021/D-023).\nexport type SectionProps = PropsWithChildren<\n  A11yProps & {\n    title?: string;\n    fill?: boolean;\n    /**\n     * DISPOSITION EN LIGNE (1.3.0) — les enfants se placent côte à côte et\n     * passent à la ligne quand la largeur manque, au lieu de s'empiler sur\n     * toute la largeur. Ajoutée pour les options d'un filtre à choix : empilées\n     * verticalement, elles donnaient à un écran de consultation l'allure d'un\n     * formulaire. Le bloc choisit un RÔLE, la primitive choisit la forme —\n     * le cliquet d'étanchéité interdit tout style chez les blocs, à raison.\n     */\n    inline?: boolean;\n  }\n>;\n\nexport interface AppButtonProps extends A11yProps {\n  label: string;\n  /**\n   * OPTIONNEL depuis D-084 — sans gestionnaire, le bouton n'est PAS pressable.\n   * Un effet que le moteur n'exécute pas ne doit pas offrir d'affordance :\n   * c'est le remède d'`APP-D002`, appliqué ici au niveau de la primitive pour\n   * qu'aucun étage au-dessus ne puisse le contourner.\n   */\n  onPress?: () => void;\n  /**\n   * `chip` (1.5.0, DET-034) — un FILTRE, pas une action : visuel de badge\n   * (le langage compact existant du système), cible tactile INTACTE à\n   * `tapTarget` — le pressable garde sa pleine hauteur autour d'un visuel\n   * compact. Jugé sur appareil : deux gros boutons pleine hauteur donnaient\n   * aux filtres plus d'importance qu'à la recherche.\n   */\n  kind?: \"primary\" | \"ghost\" | \"chip\";\n  /**\n   * État SÉLECTIONNÉ (1.5.0) — porté par `accessibilityState.selected`, comme\n   * la navigation. Ferme l'observation consignée le 2026-09-05 : un chip de\n   * filtre actif n'exposait aucun état à l'accessibilité.\n   */\n  selected?: boolean;\n  disabled?: boolean;\n  loading?: boolean;\n}\n\nexport interface TextFieldProps extends A11yProps {\n  label: string;\n  value: string;\n  onChangeText: (value: string) => void;\n  placeholder?: string;\n  error?: string;\n  loading?: boolean;\n  /** Saisie masquée (AuthFlow — mot de passe). */\n  secure?: boolean;\n}\n\nexport interface ListRowProps extends A11yProps {\n  title: string;\n  subtitle?: string;\n  badge?: string;\n  /** Texte de fin de ligne (prix, valeur, méta) — position logique RTL. */\n  trailing?: string;\n  /** Contenu de tête de ligne fourni par le bloc (avatar, icône…). */\n  leading?: ReactNode;\n  onPress?: () => void;\n}\n\n/**\n * IMAGE (1.2.0, D-087) — deux variantes seulement, décidées ici et non par\n * l'appelant : `thumb` pour une ligne de liste, `header` pour une fiche. Un\n * bloc ne porte AUCUN style (cliquet d'étanchéité) : il choisit un RÔLE, la\n * primitive choisit la forme.\n */\nexport interface AppImageProps extends A11yProps {\n  uri: string;\n  variant: \"thumb\" | \"header\";\n}\n\nexport interface BadgeProps extends A11yProps {\n  label: string;\n  tone?: \"info\" | \"success\" | \"warn\" | \"error\";\n}\n\nexport interface StateViewProps extends A11yProps {\n  state: \"loading\" | \"empty\" | \"error\";\n  title: string;\n  message?: string;\n  actionLabel?: string;\n  onAction?: () => void;\n}\n\nexport interface SpinnerProps extends A11yProps {\n  size?: \"small\" | \"large\";\n}\n\n// Le record complet — la conformité d'une implémentation est vérifiée par\n// le compilateur TypeScript (patron éprouvé au banc P-003).\nexport interface Primitives {\n  ScreenShell: ComponentType<ScreenShellProps>;\n  Section: ComponentType<SectionProps>;\n  AppText: ComponentType<AppTextProps>;\n  AppButton: ComponentType<AppButtonProps>;\n  TextField: ComponentType<TextFieldProps>;\n  AppImage: ComponentType<AppImageProps>;\n  ListRow: ComponentType<ListRowProps>;\n  Badge: ComponentType<BadgeProps>;\n  StateView: ComponentType<StateViewProps>;\n  Spinner: ComponentType<SpinnerProps>;\n}\n\nexport interface ThemeBridge {\n  scheme: Scheme;\n  setScheme: (scheme: Scheme) => void;\n}\n",
  "lib/primitives/index.ts": "// @deribfy/primitives — contrats v1 + implémentation StyleSheet+tokens (D-021).\nexport type {\n  A11yProps,\n  AppButtonProps,\n  AppImageProps,\n  AppTextProps,\n  BadgeProps,\n  ListRowProps,\n  Primitives,\n  Scheme,\n  ScreenShellProps,\n  SectionProps,\n  SpinnerProps,\n  StateViewProps,\n  TextFieldProps,\n  TextTone,\n  TextVariant,\n  ThemeBridge,\n} from \"./contracts.ts\";\nexport {\n  AppButton,\n  AppImage,\n  AppText,\n  Badge,\n  ListRow,\n  primitives,\n  ScreenShell,\n  Section,\n  Spinner,\n  StateView,\n  TextField,\n} from \"./primitives.tsx\";\n// `useStyles` rejoint l'index (D-087) : les blocs en ont besoin pour la\n// vignette de ligne, et importer un sous-chemin depuis un paquet aurait créé\n// une seconde porte d'entrée là où il n'en faut qu'une.\nexport { ThemeRoot, useStyles, useThemeBridge } from \"./theme-bridge.tsx\";\n",
  "lib/primitives/primitives.tsx": "// LES 9 PRIMITIVES v1 (dossier 3.2 validé : B2) — implémentation\n// StyleSheet + tokens maison (D-021). Simple et composable, sans mécanisme\n// « au cas où » : chaque primitive est exigée par un bloc de 3.3 ou par le\n// harnais 3.4. Les rôles a11y sont posés ici (C2) ; les contrats n'exposent\n// que testID/accessibilityLabel.\nimport { ActivityIndicator, Image, Pressable, Text, TextInput, View } from \"react-native\";\nimport type {\n  AppImageProps,\n  AppButtonProps,\n  AppTextProps,\n  BadgeProps,\n  ListRowProps,\n  Primitives,\n  ScreenShellProps,\n  SectionProps,\n  SpinnerProps,\n  StateViewProps,\n  TextFieldProps,\n  TextVariant,\n} from \"./contracts.ts\";\nimport { useStyles } from \"./theme-bridge.tsx\";\nimport type { Sheet } from \"./styles.ts\";\n\nconst VARIANT_STYLE: Record<TextVariant, keyof Sheet> = {\n  label: \"textLabel\",\n  body: \"textBody\",\n  title: \"textTitle\",\n  heading: \"textHeading\",\n};\n\nexport function ScreenShell({ children, testID, accessibilityLabel }: ScreenShellProps) {\n  const s = useStyles();\n  return (\n    // DET-017 volet 1 (D-039, dimension I) — le titre VISIBLE est retiré.\n    // Cause démontrée par deux méthodes indépendantes : ce Text et l'en-tête\n    // de navigation (`options.title`) dérivent de la MÊME donnée AIR\n    // (`screen.title`), la répétition était donc structurelle sur les 47\n    // écrans du corpus. `headerShown` n'est désactivé NULLE PART : l'en-tête\n    // natif est toujours rendu et porte désormais seul le titre, à la place\n    // que la convention de plateforme lui assigne.\n    // DET-020 (Phase 10) — le repli `accessibilityLabel ?? title` est RETIRÉ.\n    // Mesuré sur RN 0.86.3 : `AccessibilityProps.h` pose `accessible{false}`\n    // et `RCTViewComponentView.mm` lie `isAccessibilityElement` à cette prop\n    // — le label d'un conteneur non `accessible` n'est donc PAS restitué par\n    // VoiceOver. Sur Android il posait en revanche une `contentDescription`\n    // sur le conteneur racine des écrans, dont l'effet TalkBack n'a jamais\n    // été mesuré. Livrer un comportement inerte d'un côté et non mesuré de\n    // l'autre, pour un bénéfice nul, est pire que ne rien livrer.\n    // La sémantique de titre d'écran est portée par l'EN-TÊTE NATIF, qui la\n    // reçoit de la même donnée AIR et n'est désactivé nulle part.\n    // Contrat INCHANGÉ : `title` demeure requis par ScreenShellProps.\n    <View style={s.shell} testID={testID} accessibilityLabel={accessibilityLabel}>\n      {children}\n    </View>\n  );\n}\n\nexport function Section({\n  title,\n  children,\n  testID,\n  accessibilityLabel,\n  fill = false,\n  inline = false,\n}: SectionProps) {\n  const s = useStyles();\n  // DET-025 — `fill` était DÉCLARÉ par le contrat, PORTÉ par les styles,\n  // DEMANDÉ par ListBlock… et ignoré ici. La liste virtualisée n'avait donc\n  // aucun parent borné : sur appareil, le conteneur débordait de l'écran,\n  // la dernière ligne était coupée et le bloc suivant devenait inatteignable\n  // (mesuré : FlatList jusqu'à y=2400 = bas d'écran exact, `empty_state`\n  // entièrement hors écran). C'est la correction que DET-006 croyait avoir\n  // faite : le contrat et les styles étaient bons, le câblage manquait.\n  return (\n    <View\n      style={fill ? [s.section, s.sectionFill] : s.section}\n      testID={testID}\n      accessibilityLabel={accessibilityLabel}\n    >\n      {title !== undefined && <Text style={s.sectionTitle}>{title}</Text>}\n      {fill ? (\n        <View style={s.sectionFillBody}>{children}</View>\n      ) : inline ? (\n        <View style={s.sectionInlineBody}>{children}</View>\n      ) : (\n        children\n      )}\n    </View>\n  );\n}\n\nexport function AppText({\n  variant = \"body\",\n  tone = \"default\",\n  align,\n  children,\n  testID,\n  accessibilityLabel,\n}: AppTextProps) {\n  const s = useStyles();\n  return (\n    <Text\n      style={[\n        s[VARIANT_STYLE[variant]],\n        tone === \"muted\" && s.toneMuted,\n        tone === \"primary\" && s.tonePrimary,\n        tone === \"error\" && s.toneError,\n        tone === \"success\" && s.toneSuccess,\n        tone === \"warn\" && s.toneWarn,\n        align === \"center\" && s.alignCenter,\n        align === \"end\" && s.alignEnd,\n      ]}\n      testID={testID}\n      accessibilityLabel={accessibilityLabel}\n    >\n      {children}\n    </Text>\n  );\n}\n\nexport function AppButton({\n  label,\n  onPress,\n  kind = \"primary\",\n  selected,\n  disabled = false,\n  loading = false,\n  testID,\n  accessibilityLabel,\n}: AppButtonProps) {\n  const s = useStyles();\n  const ghost = kind === \"ghost\";\n  const chip = kind === \"chip\";\n  const inactive = disabled || loading;\n  return (\n    <Pressable\n      style={[chip ? s.buttonChip : s.button, ghost && s.buttonGhost, inactive && s.buttonDisabled]}\n      onPress={inactive ? undefined : onPress}\n      disabled={inactive}\n      testID={testID}\n      accessibilityRole=\"button\"\n      accessibilityLabel={accessibilityLabel ?? label}\n      accessibilityState={{\n        disabled: inactive,\n        busy: loading,\n        // 1.5.0 (DET-034) : l'état sélectionné se DIT — comme la navigation.\n        ...(selected === undefined ? {} : { selected }),\n      }}\n    >\n      {loading && <ActivityIndicator size=\"small\" />}\n      {chip ? (\n        // La CIBLE (Pressable) garde tapTarget ; le VISUEL est un badge.\n        <View style={[s.buttonChipVisuel, selected === true && s.buttonChipVisuelActif]}>\n          <Text style={[s.buttonChipText, selected === true && s.buttonChipTextActif]}>{label}</Text>\n        </View>\n      ) : (\n        <Text style={[s.buttonText, ghost && s.buttonGhostText]}>{label}</Text>\n      )}\n    </Pressable>\n  );\n}\n\nexport function TextField({\n  label,\n  value,\n  onChangeText,\n  placeholder,\n  error,\n  loading = false,\n  secure = false,\n  testID,\n  accessibilityLabel,\n}: TextFieldProps) {\n  const s = useStyles();\n  return (\n    <View style={s.fieldWrap} testID={testID}>\n      {/* DET-033 : un libellé VIDE ne rend rien — un champ compact (recherche)\n          porte son sens par `placeholder` + `accessibilityLabel`, sans ligne\n          fantôme au-dessus. Contrat inchangé. */}\n      {label === \"\" ? null : <Text style={s.fieldLabel}>{label}</Text>}\n      <View style={s.fieldRow}>\n        <TextInput\n          style={[s.input, error !== undefined && s.inputError]}\n          value={value}\n          onChangeText={onChangeText}\n          placeholder={placeholder}\n          secureTextEntry={secure}\n          accessibilityLabel={accessibilityLabel ?? label}\n        />\n        {loading && <ActivityIndicator size=\"small\" style={s.fieldSpinner} />}\n      </View>\n      {error !== undefined && (\n        <Text style={s.fieldError} accessibilityRole=\"alert\">\n          {error}\n        </Text>\n      )}\n    </View>\n  );\n}\n\nexport function AppImage({ uri, variant, testID, accessibilityLabel }: AppImageProps) {\n  const s = useStyles();\n  return (\n    <Image\n      testID={testID}\n      accessibilityLabel={accessibilityLabel}\n      source={{ uri }}\n      style={variant === \"thumb\" ? s.imageThumb : s.imageHeader}\n      accessibilityIgnoresInvertColors\n    />\n  );\n}\n\nexport function ListRow({\n  title,\n  subtitle,\n  badge,\n  trailing,\n  leading,\n  onPress,\n  testID,\n  accessibilityLabel,\n}: ListRowProps) {\n  const s = useStyles();\n  const body = (\n    <>\n      {leading !== undefined && <View style={s.rowLeading}>{leading}</View>}\n      <View style={s.rowBody}>\n        <Text style={s.rowTitle}>{title}</Text>\n        {subtitle !== undefined && <Text style={s.rowSubtitle}>{subtitle}</Text>}\n        {badge !== undefined && <Badge label={badge} />}\n      </View>\n      {trailing !== undefined && <Text style={s.rowTrailing}>{trailing}</Text>}\n    </>\n  );\n  if (onPress === undefined) {\n    return (\n      <View style={s.row} testID={testID} accessibilityLabel={accessibilityLabel}>\n        {body}\n      </View>\n    );\n  }\n  return (\n    <Pressable\n      style={s.row}\n      onPress={onPress}\n      testID={testID}\n      accessibilityRole=\"button\"\n      accessibilityLabel={accessibilityLabel ?? title}\n    >\n      {body}\n    </Pressable>\n  );\n}\n\nexport function Badge({ label, tone = \"info\", testID, accessibilityLabel }: BadgeProps) {\n  const s = useStyles();\n  return (\n    <View style={s.badge} testID={testID} accessibilityLabel={accessibilityLabel}>\n      <Text\n        style={[\n          s.badgeText,\n          tone === \"success\" && s.badgeSuccess,\n          tone === \"warn\" && s.badgeWarn,\n          tone === \"error\" && s.badgeError,\n        ]}\n      >\n        {label}\n      </Text>\n    </View>\n  );\n}\n\nexport function StateView({\n  state,\n  title,\n  message,\n  actionLabel,\n  onAction,\n  testID,\n  accessibilityLabel,\n}: StateViewProps) {\n  const s = useStyles();\n  return (\n    <View\n      style={s.stateWrap}\n      testID={testID}\n      accessibilityLabel={accessibilityLabel ?? title}\n      accessibilityRole={state === \"error\" ? \"alert\" : undefined}\n    >\n      {state === \"loading\" && <ActivityIndicator size=\"large\" />}\n      <Text style={[s.stateTitle, state === \"error\" && s.stateTitleError]}>{title}</Text>\n      {message !== undefined && <Text style={s.stateMessage}>{message}</Text>}\n      {actionLabel !== undefined && onAction !== undefined && (\n        <AppButton label={actionLabel} onPress={onAction} kind=\"ghost\" />\n      )}\n    </View>\n  );\n}\n\nexport function Spinner({ size = \"small\", testID, accessibilityLabel }: SpinnerProps) {\n  return (\n    <ActivityIndicator size={size} testID={testID} accessibilityLabel={accessibilityLabel} />\n  );\n}\n\n// Conformité au contrat vérifiée par le compilateur (patron du banc P-003).\nexport const primitives: Primitives = {\n  ScreenShell,\n  Section,\n  AppText,\n  AppButton,\n  TextField,\n  AppImage,\n  ListRow,\n  Badge,\n  StateView,\n  Spinner,\n};\n",
  "lib/primitives/styles.ts": "// FEUILLES DE STYLE — StyleSheet + tokens maison (D-021). SEUL module (avec\n// primitives.tsx) à connaître le moteur de styling : les contrats n'en savent\n// rien (étanchéité §22). Tokens consommés depuis la SOURCE UNIQUE (3.1).\n// RTL : propriétés LOGIQUES exclusivement (start/end) — miroir automatique\n// prouvé au banc, verrouillé par tests/rtl-ratchet.test.ts.\n// DESIGN SYSTEM v2 (P-007, Phase 10) : plus AUCUNE valeur de design en dur —\n// graisses, pas fin d'espacement et opacité d'état viennent des tokens ;\n// l'accent n'est plus utilisé comme couleur de texte (encre dérivée).\nimport { theme } from \"../tokens\";\nimport { StyleSheet } from \"react-native\";\nimport type { Scheme } from \"./contracts.ts\";\n\nexport type Palette = (typeof theme.color)[Scheme];\n\nconst makeSheet = (c: Palette) =>\n  StyleSheet.create({\n    // — ScreenShell —\n    shell: { flex: 1, backgroundColor: c.bg },\n    shellTitle: {\n      fontSize: theme.font.heading,\n      fontWeight: theme.fontWeight.bold,\n      color: c.text,\n      padding: theme.space.lg,\n    },\n    // — Section —\n    section: { padding: theme.space.lg },\n    // DET-006 : section qui remplit et BORNE sa hauteur, plus conteneur\n    // d'enfants borné — la liste virtualisée y retrouve une fenêtre finie.\n    sectionFill: { flex: 1 },\n    sectionFillBody: { flex: 1 },\n    // Disposition EN LIGNE (1.3.0) : les enfants se suivent et passent à la\n    // ligne. `gap` remplace des marges par enfant — aucune propriété physique,\n    // la dimension F (RTL par propriétés logiques) reste tenue.\n    sectionInlineBody: {\n      flexDirection: \"row\",\n      flexWrap: \"wrap\",\n      alignItems: \"center\",\n      gap: theme.space.sm,\n    },\n    sectionTitle: {\n      fontSize: theme.font.title,\n      fontWeight: theme.fontWeight.semibold,\n      color: c.text,\n      marginBottom: theme.space.md,\n    },\n    // — AppText (variantes = tokens de police ; tons = tokens de couleur) —\n    textLabel: { fontSize: theme.font.label, color: c.text },\n    textBody: { fontSize: theme.font.body, color: c.text },\n    textTitle: { fontSize: theme.font.title, fontWeight: theme.fontWeight.semibold, color: c.text },\n    textHeading: { fontSize: theme.font.heading, fontWeight: theme.fontWeight.bold, color: c.text },\n    toneMuted: { color: c.muted },\n    tonePrimary: { color: c.primaryText },\n    toneError: { color: c.error },\n    toneSuccess: { color: c.success },\n    toneWarn: { color: c.warn },\n    alignStart: { textAlign: \"auto\" },\n    alignCenter: { textAlign: \"center\" },\n    // `justify` n'existe pas ; « end » logique = right en LTR, miroir en RTL\n    // est géré par writingDirection native — on utilise l'axe logique :\n    alignEnd: { alignSelf: \"flex-end\" },\n    // — AppButton —\n    button: {\n      minHeight: theme.size.tapTarget,\n      backgroundColor: c.primary,\n      borderRadius: theme.radius.md,\n      paddingVertical: theme.space.md,\n      paddingHorizontal: theme.space.lg,\n      alignItems: \"center\",\n      flexDirection: \"row\",\n      justifyContent: \"center\",\n      gap: theme.space.sm,\n    },\n    buttonGhost: {\n      backgroundColor: \"transparent\",\n      borderWidth: 1,\n      borderColor: c.primary,\n    },\n    buttonDisabled: { opacity: theme.opacity.disabled },\n    // — chip (1.5.0, DET-034) : la CIBLE garde tapTarget, le VISUEL est un\n    // badge. La discrétion est dans le rendu, jamais dans la zone de toucher.\n    // Style de BASE du chip (jamais empilé sur `button` : rien à écraser,\n    // donc aucune valeur en dur — l'instrument E le vérifie).\n    buttonChip: {\n      minHeight: theme.size.tapTarget,\n      justifyContent: \"center\",\n      alignItems: \"flex-start\",\n    },\n    buttonChipVisuel: {\n      backgroundColor: c.badgeBg,\n      borderRadius: theme.radius.sm,\n      paddingHorizontal: theme.space.sm,\n      paddingVertical: theme.space.xxs,\n    },\n    buttonChipVisuelActif: { backgroundColor: c.primary },\n    buttonChipText: { color: c.primaryText, fontWeight: theme.fontWeight.semibold, fontSize: theme.font.label },\n    buttonChipTextActif: { color: c.onPrimary },\n    buttonText: { color: c.onPrimary, fontWeight: theme.fontWeight.semibold, fontSize: theme.font.body },\n    buttonGhostText: { color: c.primaryText },\n    // — TextField —\n    fieldWrap: { marginBottom: theme.space.md },\n    fieldLabel: {\n      fontSize: theme.font.label,\n      color: c.muted,\n      marginBottom: theme.space.xs,\n    },\n    fieldRow: { flexDirection: \"row\", alignItems: \"center\" },\n    input: {\n      flex: 1,\n      borderWidth: 1,\n      borderColor: c.border,\n      borderRadius: theme.radius.sm,\n      minHeight: theme.size.tapTarget,\n      paddingHorizontal: theme.space.md,\n      paddingVertical: theme.space.sm,\n      color: c.text,\n      backgroundColor: c.surface,\n      fontSize: theme.font.body,\n    },\n    inputError: { borderColor: c.error },\n    fieldError: {\n      color: c.error,\n      fontSize: theme.font.label,\n      marginTop: theme.space.xs,\n    },\n    fieldSpinner: { marginStart: theme.space.sm },\n    // — NAVIGATION PRINCIPALE (D-086) — compacte PAR CONSTRUCTION : sa hauteur\n    // est bornée par la cible tactile, pas par le contenu. C'est ce qui la\n    // distingue des quatre gros boutons qu'elle remplace, lesquels grandissaient\n    // avec leur libellé.\n    // PANNEAU DE NAVIGATION (1.3.0) — la barre était un simple filet posé au\n    // bas de l'écran : quatre libellés séparés du contenu par un trait. Elle\n    // devient un PANNEAU détaché, posé sur le fond, avec un état actif porté\n    // par une pastille et non par la seule graisse du texte.\n    // Contraintes tenues, et vérifiées : `minHeight` reste `tapTarget` (48 dp,\n    // mesuré conforme sur A17) ; aucune valeur en dur, tout vient des tokens\n    // (dimension D) ; aucune propriété physique (dimension F) ; aucune limite\n    // de lignes sur les libellés (dimension E — le mot exact est volontairement\n    // absent, l'instrument le cherche par sous-chaîne sans distinguer un\n    // commentaire du code).\n    primaryNav: {\n      flexDirection: \"row\",\n      backgroundColor: c.surface,\n      borderTopWidth: 1,\n      borderTopColor: c.border,\n      paddingTop: theme.space.sm,\n      paddingHorizontal: theme.space.sm,\n      gap: theme.space.xs,\n    },\n    primaryNavItem: {\n      flex: 1,\n      minHeight: theme.size.tapTarget,\n      alignItems: \"center\",\n      justifyContent: \"center\",\n      paddingHorizontal: theme.space.xs,\n      paddingVertical: theme.space.xs,\n      borderRadius: theme.radius.md,\n    },\n    // ÉTAT ACTIF LISIBLE SANS LIRE — pastille pleine sur l'onglet courant.\n    primaryNavItemActive: {\n      flex: 1,\n      minHeight: theme.size.tapTarget,\n      alignItems: \"center\",\n      justifyContent: \"center\",\n      paddingHorizontal: theme.space.xs,\n      paddingVertical: theme.space.xs,\n      borderRadius: theme.radius.md,\n      backgroundColor: c.badgeBg,\n    },\n    // Taille du glyphe d'onglet — portée par un TOKEN, jamais par un nombre\n    // écrit dans le composant : la dimension D interdit toute valeur en dur.\n    primaryNavIcon: { fontSize: theme.font.heading },\n    primaryNavLabel: { fontSize: theme.font.label, color: c.muted },\n    primaryNavLabelActive: {\n      fontSize: theme.font.label,\n      color: c.primaryText,\n      fontWeight: theme.fontWeight.semibold,\n    },\n    // — ListRow —\n    row: {\n      minHeight: theme.size.tapTarget,\n      backgroundColor: c.surface,\n      borderColor: c.border,\n      borderWidth: 1,\n      borderRadius: theme.radius.md,\n      padding: theme.space.md,\n      marginHorizontal: theme.space.lg,\n      marginVertical: theme.space.xs,\n      flexDirection: \"row\",\n      alignItems: \"center\",\n    },\n    rowLeading: { marginEnd: theme.space.md },\n    // VIGNETTE DE LIGNE (1.2.0, D-087) — carrée, bornée, à gauche du texte.\n    // C'est la composition d'un catalogue : image à gauche, titre et\n    // description au centre qui prennent tout l'espace restant (`rowBody`\n    // flex:1), prix à droite. Rien n'est centré, rien ne reste étroit.\n    // VISUEL D'EN-TÊTE — pleine largeur, hauteur bornée : c'est la hiérarchie\n    // d'une fiche produit. `width: \"100%\"` exploite l'espace horizontal au lieu\n    // de laisser un visuel étroit centré.\n    imageHeader: {\n      width: \"100%\",\n      minHeight: theme.size.tapTarget * 3,\n      borderRadius: theme.radius.md,\n      backgroundColor: c.border,\n      marginBottom: theme.space.md,\n    },\n    imageThumb: {\n      width: theme.size.tapTarget,\n      height: theme.size.tapTarget,\n      borderRadius: theme.radius.sm,\n      backgroundColor: c.border,\n    },\n    rowBody: { flex: 1 },\n    rowTitle: { fontSize: theme.font.body, fontWeight: theme.fontWeight.semibold, color: c.text },\n    rowSubtitle: {\n      fontSize: theme.font.label,\n      color: c.muted,\n      marginTop: theme.space.xs,\n    },\n    rowTrailing: {\n      fontSize: theme.font.body,\n      fontWeight: theme.fontWeight.bold,\n      // v2 (DET-019) : encre DÉRIVÉE de l'accent — l'accent lui-même reste\n      // réservé aux FONDS et aux bordures, où le seuil 4,5:1 ne s'applique\n      // pas au texte. Mesuré : 2,95:1 avant, 4,57:1 après.\n      color: c.primaryText,\n      marginStart: theme.space.md,\n    },\n    // — Badge —\n    badge: {\n      backgroundColor: c.badgeBg,\n      borderRadius: theme.radius.sm,\n      paddingHorizontal: theme.space.sm,\n      paddingVertical: theme.space.xxs,\n      alignSelf: \"flex-start\",\n      marginTop: theme.space.xs,\n    },\n    badgeText: { fontSize: theme.font.label, color: c.muted },\n    badgeSuccess: { color: c.success },\n    badgeWarn: { color: c.warn },\n    badgeError: { color: c.error },\n    // — StateView —\n    stateWrap: {\n      flex: 1,\n      alignItems: \"center\",\n      justifyContent: \"center\",\n      padding: theme.space.xl,\n      gap: theme.space.md,\n    },\n    stateTitle: {\n      fontSize: theme.font.title,\n      fontWeight: theme.fontWeight.semibold,\n      color: c.text,\n      textAlign: \"center\",\n    },\n    stateMessage: {\n      fontSize: theme.font.body,\n      color: c.muted,\n      textAlign: \"center\",\n    },\n    stateTitleError: { color: c.error },\n  });\n\nexport type Sheet = ReturnType<typeof makeSheet>;\n\n// Pré-calcul UNIQUE des deux feuilles (patron gagnant du banc : la bascule\n// de thème ne recrée aucun style, elle change de feuille).\nexport const SHEETS: Record<Scheme, Sheet> = {\n  light: makeSheet(theme.color.light),\n  dark: makeSheet(theme.color.dark),\n};\n",
  "lib/primitives/theme-bridge.tsx": "// PONT DE THÈME (D1, dossier 3.2 validé) — patron GAGNANT du banc P-003\n// (bascule light/dark en 2 frames : les deux feuilles de style sont\n// pré-calculées une fois au chargement, la bascule ne fait que changer de\n// feuille via le contexte). Liaison STATIQUE aux tokens : la variance par\n// app est un acte de COMPILATION (le compilateur émettra un module de\n// tokens propre à chaque app — modèle copie-régénérable §3), jamais un\n// mécanisme runtime.\nimport { createContext, useContext, useMemo, useState } from \"react\";\nimport type { PropsWithChildren } from \"react\";\nimport type { Scheme, ThemeBridge } from \"./contracts.ts\";\nimport { SHEETS, type Sheet } from \"./styles.ts\";\n\nconst SchemeContext = createContext<ThemeBridge>({\n  scheme: \"light\",\n  setScheme: () => undefined,\n});\n\nexport function ThemeRoot({\n  children,\n  initialScheme = \"light\",\n}: PropsWithChildren<{ initialScheme?: Scheme }>) {\n  const [scheme, setScheme] = useState<Scheme>(initialScheme);\n  const value = useMemo(() => ({ scheme, setScheme }), [scheme]);\n  return <SchemeContext.Provider value={value}>{children}</SchemeContext.Provider>;\n}\n\nexport function useThemeBridge(): ThemeBridge {\n  return useContext(SchemeContext);\n}\n\nexport function useStyles(): Sheet {\n  return SHEETS[useContext(SchemeContext).scheme];\n}\n",
  "lib/runtime/air-runtime.tsx": "// RUNTIME COPIÉ (compilateur 4.3, D-026 Option C) — pont UNIQUE et TESTÉ\n// entre les données canoniques d'écran (modules .data générés) et les\n// contrats des Smart Blocks gelés. Les écrans générés restent du code\n// STRUCTUREL lisible (séquence de blocs explicite, points d'insertion de\n// slots) ; toute la logique de correspondance vit ici, écrite une fois.\n// F3 : AUCUN texte naturel dans ce module — tous les libellés viennent des\n// données AIR ; les erreurs internes sont des codes.\n// Effets d'actions en v1 compilateur : `navigate` est câblé ; les effets\n// `capability`/`mutation`/`slot` sont des non-opérations STRUCTURÉES\n// (implémentations : Phases 5+/9 — lecture consignée D-028).\nimport { useEffect, useMemo, useState, useSyncExternalStore } from \"react\";\n// E1/E2 (D-129) — la vérité des lignes visibles vit dans un module PUR.\nimport { lignesVisibles, optionsDistinctes } from \"./list-pipeline\";\nimport type { FiltreEffectif, OperateurFiltre } from \"./list-pipeline\";\nimport { useNavigation } from \"@react-navigation/native\";\nimport {\n  ButtonBlock,\n  DetailHeaderBlock,\n  EmptyStateBlock,\n  FormBlock,\n  HeaderBlock,\n  ListBlock,\n} from \"../blocks/components\";\nimport type { FormFieldSpec, ListItemData } from \"../blocks/contracts\";\nimport { useDataProvider } from \"./data-provider\";\nimport { useSlotRegistry } from \"./slot-provider\";\nimport { useCapabilityProvider } from \"./capability-provider\";\nimport { useSessionProvider } from \"./session-provider\";\nimport { useAllFormValues, useFormValues } from \"./form-state\";\n\nexport interface AirEffectData {\n  kind: \"navigate\" | \"capability\" | \"mutation\" | \"slot\";\n  screenId?: string;\n  /** Effet `mutation` (D-061) — l'entité écrite et l'opération. */\n  entityId?: string;\n  operation?: string;\n  /** Écran atteint UNE FOIS l'écriture réussie (1.5.0, D-070). */\n  thenScreenId?: string;\n  /** Effet `capability` (D-059) — transporté pour être INVOQUÉ, plus ignoré. */\n  capability?: string;\n  method?: string;\n  params?: Readonly<Record<string, unknown>>;\n}\n\nexport type AirBlockVisibility =\n  | { kind: \"entity_empty\" | \"entity_not_empty\"; entityId: string }\n  /** 1.11.0 (Phase 4) — prédicat de SESSION : aucune entité interrogée. */\n  | { kind: \"session_authenticated\" | \"session_anonymous\" };\n\nexport interface AirBlockInstanceData {\n  id: string;\n  blockType: string;\n  entityId?: string;\n  /** Condition de rendu (AIR 1.1.0) — absente = bloc toujours visible. */\n  visibleWhen?: AirBlockVisibility;\n  props: Readonly<Record<string, unknown>>;\n}\n\n/** Règle de validation (AIR `rules`, D-062) — appliquée AVANT toute écriture. */\nexport interface AirRuleData {\n  entityId: string;\n  assertions: readonly {\n    fieldId: string;\n    operator: string;\n    /**\n     * DÉFAUT CORRIGÉ (D-072) — ce type était écrit à la main et **plus étroit\n     * que le schéma** : `jsonLeafSchema` autorise les TABLEAUX, qu'emploie\n     * l'opérateur `in` (`value: [\"payee\", \"annulee\", …]`). Résultat : toute\n     * application portant une règle `in` **ne compilait pas**. Mesuré sur le\n     * corpus : 11 documents sur 14.\n     */\n    value?: string | number | boolean | null | readonly (string | number | boolean | null)[];\n  }[];\n}\n\nexport interface AirFieldData {\n  id: string;\n  name: string;\n  type: string;\n  /** Traversée de relation (1.4.0, D-064) — vers quoi, et quoi montrer. */\n  referencesEntityId?: string;\n  referenceDisplayFieldId?: string;\n  /** Libellés d'affichage (AIR 1.10.0, DET-032) — RÉSOLUS par le compilateur\n      dans la langue de l'app ; absents = comportement 1.9.0 (name/valeur). */\n  label?: string;\n  enumLabels?: Readonly<Record<string, string>>;\n}\n\nexport interface AirSlotInvocationData {\n  slotId: string;\n  inputs: readonly {\n    port: string;\n    source:\n      | { kind: \"entity_rows\"; entityId: string }\n      | { kind: \"literal\"; value: unknown };\n  }[];\n  outputs: readonly { port: string; blockId: string; prop: string }[];\n}\n\nexport interface AirScreenData {\n  screenId: string;\n  title: string;\n  blocks: readonly AirBlockInstanceData[];\n  actions: Readonly<Record<string, AirEffectData>>;\n  uiActionsByBlock: Readonly<Record<string, string>>;\n  entities: Readonly<Record<string, { fields: readonly AirFieldData[] }>>;\n  /** Slots LIÉS dont au moins une sortie alimente un bloc de cet écran (1.3.0). */\n  slotInvocations?: readonly AirSlotInvocationData[];\n  /** Règles de validation des entités écrites depuis cet écran (D-062). */\n  rules?: readonly AirRuleData[];\n  /** Actions de CYCLE DE VIE de cet écran (D-068) — à l'ouverture, à la sortie. */\n  lifecycle?: {\n    onOpen?: readonly string[];\n    onClose?: readonly string[];\n  };\n}\n\nexport interface AirScreenProps {\n  route?: { params?: { itemId?: string } };\n}\n\ninterface BlockRef {\n  screen: AirScreenData;\n  blockId: string;\n}\n\n/**\n * APPLICATION DES RÈGLES (D-062) — `air.rules` n'était lu NULLE PART.\n *\n * `rulesEnforced: false` : un document pouvait déclarer « le téléphone est\n * obligatoire » et l'app écrivait sans lui. La règle est désormais évaluée\n * AVANT l'écriture, et une violation ANNULE la mutation.\n *\n * Fermé par construction : seuls les opérateurs du schéma sont évalués, aucune\n * expression arbitraire. Un opérateur inconnu ne bloque JAMAIS — refuser sur\n * une règle qu'on ne sait pas lire serait s'arroger un jugement.\n */\nfunction reglesRespectees(\n  regles: readonly AirRuleData[] | undefined,\n  entityId: string,\n  valeurs: Readonly<Record<string, string>>,\n): boolean {\n  for (const regle of regles ?? []) {\n    if (regle.entityId !== entityId) continue;\n    for (const a of regle.assertions) {\n      const brut = valeurs[a.fieldId];\n      const nombre = brut === undefined ? Number.NaN : Number(brut);\n      const attendu = a.value;\n      switch (a.operator) {\n        case \"required\":\n          if (brut === undefined || brut.trim() === \"\") return false;\n          break;\n        case \"eq\":\n          if (String(brut) !== String(attendu)) return false;\n          break;\n        case \"neq\":\n          if (String(brut) === String(attendu)) return false;\n          break;\n        case \"gt\":\n          if (!(nombre > Number(attendu))) return false;\n          break;\n        case \"gte\":\n          if (!(nombre >= Number(attendu))) return false;\n          break;\n        case \"lt\":\n          if (!(nombre < Number(attendu))) return false;\n          break;\n        case \"lte\":\n          if (!(nombre <= Number(attendu))) return false;\n          break;\n        case \"in\":\n          if (!Array.isArray(attendu) || !attendu.map(String).includes(String(brut))) return false;\n          break;\n        case \"matches\":\n          if (brut === undefined || !new RegExp(String(attendu)).test(brut)) return false;\n          break;\n        default:\n          break;\n      }\n    }\n  }\n  return true;\n}\n\nfunction block(screen: AirScreenData, blockId: string): AirBlockInstanceData {\n  const found = screen.blocks.find((b) => b.id === blockId);\n  if (found === undefined) throw new Error(`AIR_RUNTIME_BLOCK_MISSING:${blockId}`);\n  return found;\n}\n\n/**\n * INVOCATION DES CODE SLOTS (1.3.0, D-058).\n *\n * Un slot LIÉ est exécuté à l'ouverture de l'écran, ses entrées prises à la\n * source déclarée, ses sorties écrites dans les props des blocs ciblés.\n *\n * Trois refus délibérés :\n * - **slot absent du registre** → aucune surcharge. Le bloc garde la prop que le\n *   document a déclarée. On n'invente pas une valeur pour un code non fourni.\n * - **slot qui lève** → aucune surcharge, l'écran continue de rendre. Un slot est\n *   du code d'auteur sous influence potentielle du prompt utilisateur (§4) : il\n *   ne doit jamais pouvoir abattre l'application.\n * - **port de sortie absent du résultat** → aucune surcharge pour CE port. Un\n *   `undefined` écrit dans une prop serait pire que l'absence.\n */\nfunction useSlotOverrides(\n  screen: AirScreenData,\n): Readonly<Record<string, Readonly<Record<string, unknown>>>> {\n  const provider = useDataProvider();\n  const registry = useSlotRegistry();\n  const invocations = screen.slotInvocations;\n  return useMemo(() => {\n    const out: Record<string, Record<string, unknown>> = {};\n    for (const invocation of invocations ?? []) {\n      const fn = registry[invocation.slotId];\n      if (fn === undefined) continue;\n      const entrees: Record<string, unknown> = {};\n      for (const { port, source } of invocation.inputs) {\n        entrees[port] =\n          source.kind === \"entity_rows\"\n            ? provider.listInstances(source.entityId).map((i) => i.values)\n            : source.value;\n      }\n      let resultat: Readonly<Record<string, unknown>>;\n      try {\n        resultat = fn(entrees);\n      } catch {\n        continue;\n      }\n      for (const { port, blockId, prop } of invocation.outputs) {\n        const valeur = resultat[port];\n        if (valeur === undefined) continue;\n        (out[blockId] ??= {})[prop] = valeur;\n      }\n    }\n    return out;\n  }, [invocations, registry, provider]);\n}\n\n/** Props du bloc, surchargées par les sorties de slot qui le ciblent. */\nfunction useBlockProps(\n  screen: AirScreenData,\n  blockId: string,\n): Readonly<Record<string, unknown>> {\n  const overrides = useSlotOverrides(screen);\n  const base = block(screen, blockId).props;\n  const surcharge = overrides[blockId];\n  return surcharge === undefined ? base : { ...base, ...surcharge };\n}\n\n/**\n * État de la source de données pour un bloc (D-060).\n *\n * `loading` et `error` ne sont rendus que si le document a DÉCLARÉ leur titre :\n * le moteur n'invente aucun texte (F3), exactement comme pour `empty` depuis\n * l'origine. Un fournisseur sans `status` laisse le comportement de 1.0.0\n * inchangé.\n */\nfunction useDataStatus(entityId: string | undefined): \"loading\" | \"ready\" | \"error\" {\n  const provider = useDataProvider();\n  if (entityId === undefined || provider.status === undefined) return \"ready\";\n  return provider.status(entityId);\n}\n\n/**\n * Visibilité conditionnelle d'un bloc (AIR 1.1.0, D-044).\n *\n * Défaut corrigé : un bloc `empty_state` était rendu SANS condition, donc un\n * état vide s'affichait pendant que des données étaient présentes — observé\n * sur appareil, mesuré sur 19 écrans. Le prédicat est évalué sur la MÊME\n * source que la liste (le provider de données) : les deux ne peuvent donc\n * pas se contredire.\n */\nfunction useBlockVisible(screen: AirScreenData, blockId: string): boolean {\n  const provider = useDataProvider();\n  // 1.11.0 — la session est lue INCONDITIONNELLEMENT : un hook ne se place pas\n  // derrière une condition. Sans fournisseur, elle répond ANONYME.\n  const session = useSessionProvider();\n  const abonnerSession = useMemo(\n    () => (ecouteur: () => void) => session.abonner(ecouteur),\n    [session],\n  );\n  const authentifie = useSyncExternalStore(\n    abonnerSession,\n    () => session.estAuthentifie(),\n    () => session.estAuthentifie(),\n  );\n  const condition = block(screen, blockId).visibleWhen;\n  if (condition === undefined) return true;\n  // Discrimination POSITIVE sur les prédicats de DONNÉES : eux seuls portent\n  // une entité. Exclure les autres ne suffit pas à restreindre le type.\n  if (condition.kind === \"entity_empty\" || condition.kind === \"entity_not_empty\") {\n    const vide = provider.listInstances(condition.entityId).length === 0;\n    return condition.kind === \"entity_empty\" ? vide : !vide;\n  }\n  return condition.kind === \"session_authenticated\" ? authentifie : !authentifie;\n}\n\n/**\n * TRAVERSÉE DE RELATION (D-064) — `relationTraversal: false` signifiait qu'un\n * champ `reference` s'affichait en IDENTIFIANT BRUT : « ent_plat_003 » au lieu\n * de « Thiéboudienne ». Mesuré : 6 occurrences au corpus.\n *\n * La résolution n'a lieu que si le document a DÉCLARÉ quoi montrer. Sans\n * déclaration, l'identifiant reste affiché — on ne devine pas.\n */\nfunction useResolveField(\n  screen: AirScreenData,\n  entityId: string | undefined,\n): (fieldId: string, brut: string | undefined) => string | undefined {\n  const provider = useDataProvider();\n  return (fieldId, brut) => {\n    if (brut === undefined || entityId === undefined) return brut;\n    const champ = screen.entities[entityId]?.fields.find((f) => f.id === fieldId);\n    const cible = champ?.referencesEntityId;\n    const affiche = champ?.referenceDisplayFieldId;\n    if (cible !== undefined && affiche !== undefined) {\n      return provider.getInstance(cible, brut)?.values[affiche] ?? brut;\n    }\n    // DET-032 — un code d'enum ne se montre pas : si le document a déclaré un\n    // libellé pour cette valeur, c'est LUI qui s'affiche. Données, filtrage et\n    // testID continuent de porter la valeur brute.\n    return champ?.enumLabels?.[brut] ?? brut;\n  };\n}\n\nfunction str(value: unknown): string | undefined {\n  return typeof value === \"string\" ? value : undefined;\n}\n\n/** E1 (D-129) — lecture sûre d'un prop tableau de chaînes du flat config. */\nfunction strArray(value: unknown): readonly string[] {\n  return Array.isArray(value) ? value.filter((v): v is string => typeof v === \"string\") : [];\n}\n\nfunction useDispatch(screen: AirScreenData) {\n  const navigation = useNavigation();\n  const capabilities = useCapabilityProvider();\n  const data = useDataProvider();\n  // D-083 : une action `mutation` portée par un BOUTON n'a aucune valeur propre.\n  // Les documents générés câblent pourtant « Valider » sur un bouton, pas sur le\n  // formulaire. Sans cette lecture, l'écriture partait vide et la règle de\n  // validation la refusait — en silence.\n  const saisies = useAllFormValues();\n  return useMemo(\n    () => (actionId: string | undefined, values?: Readonly<Record<string, string>>) => {\n      if (actionId === undefined) return;\n      const effect = screen.actions[actionId];\n      if (effect?.kind === \"navigate\" && effect.screenId !== undefined) {\n        (navigation.navigate as (name: string) => void)(effect.screenId);\n        return;\n      }\n      // CAPABILITY (D-059) : l'effet n'est plus AVALÉ. Il est présenté au\n      // fournisseur, qui répond s'il l'a honoré. Sans implémentation fournie,\n      // le défaut REFUSE ET TRACE — il ne prétend jamais avoir agi.\n      if (effect?.kind === \"capability\" && effect.capability !== undefined) {\n        // Phase 4 : les valeurs SAISIES accompagnent l'appel, exactement comme\n        // pour les mutations (D-061/D-083). Sans elles, une connexion partirait\n        // sans identité — l'effet s'exécuterait, et ne pourrait rien établir.\n        // Les params DÉCLARÉS restent prioritaires : ils sont la configuration\n        // du document, la saisie est la donnée de l'instant.\n        capabilities.invoke({\n          capability: effect.capability,\n          method: effect.method ?? \"\",\n          params: { ...(values ?? saisies), ...(effect.params ?? {}) },\n        });\n        return;\n      }\n      // MUTATION (D-061) : l'effet n'est plus une non-opération. L'écriture est\n      // présentée au fournisseur de données ; un fournisseur en LECTURE SEULE\n      // n'expose pas la méthode et l'appel est simplement absent — jamais un\n      // faux succès.\n      if (effect?.kind === \"mutation\" && effect.entityId !== undefined) {\n        const cible = effect.entityId;\n        const saisie = values ?? saisies;\n        // D-062 : une écriture qui viole une règle déclarée est ANNULÉE.\n        if (!reglesRespectees(screen.rules, cible, saisie)) return;\n        let ecrit = false;\n        if (effect.operation === \"create\") ecrit = data.create?.(cible, saisie) ?? false;\n        else if (effect.operation === \"update\") {\n          const id = saisie.id;\n          if (id !== undefined) ecrit = data.update?.(cible, id, saisie) ?? false;\n        } else if (effect.operation === \"delete\") {\n          const id = saisie.id;\n          if (id !== undefined) ecrit = data.remove?.(cible, id) ?? false;\n        }\n        // D-070 : on ne navigue QUE si l'écriture a réussi. Envoyer l'utilisateur\n        // sur un écran de confirmation après un refus serait un mensonge de\n        // l'interface — la faute exacte que ce chantier traque.\n        if (ecrit && effect.thenScreenId !== undefined) {\n          (navigation.navigate as (name: string) => void)(effect.thenScreenId);\n        }\n        return;\n      }\n      // slot : invoqué au RENDU, pas ici.\n    },\n    [navigation, screen, capabilities, data, saisies],\n  );\n}\n\nfunction useItemNavigate(screen: AirScreenData, blockId: string) {\n  const navigation = useNavigation();\n  const actionId = screen.uiActionsByBlock[blockId];\n  const effect = actionId === undefined ? undefined : screen.actions[actionId];\n  // AFFORDANCE : sans effet `navigate`, l'AIR ne promet RIEN sur cette ligne —\n  // elle ne doit donc pas être pressable. Retourner une fonction inerte rendait\n  // chaque ligne appuyable et muette : 46 lignes sur les 2 slices [MESURÉ à\n  // l'exécution, APP-D002]. Le contrat de bloc sait déjà ne câbler aucun\n  // `onPress` quand `onItemPress` est absent (`components.tsx`) ; il fallait le\n  // lui dire ici. On ne FABRIQUE aucun comportement : on retire une promesse\n  // que rien ne fondait.\n  if (effect?.kind !== \"navigate\" || effect.screenId === undefined) return undefined;\n  const cible = effect.screenId;\n  return (itemId: string) => {\n    (\n      navigation.navigate as (name: string, params: { itemId: string }) => void\n    )(cible, { itemId });\n  };\n}\n\n/**\n * CYCLE DE VIE D'UN ÉCRAN (D-068) — `triggers: [\"ui\"]` signifiait que le moteur\n * n'exécutait QUE les actions déclenchées par un appui. **62 actions\n * `lifecycle` du corpus étaient déclarées et purement ignorées** — un pan entier\n * du contrat d'action sans aucune implémentation.\n *\n * Les actions d'ouverture sont exécutées au montage, celles de sortie au\n * démontage. Le dispatcher décide ensuite, effet par effet, si quelque chose se\n * produit : une action `lifecycle` dont l'effet reste hors enveloppe n'est PAS\n * rendue vivante par ce câblage.\n */\nexport function AirScreenLifecycle({ screen }: { screen: AirScreenData }) {\n  const dispatch = useDispatch(screen);\n  const cycle = screen.lifecycle;\n  useEffect(() => {\n    for (const id of cycle?.onOpen ?? []) dispatch(id);\n    return () => {\n      for (const id of cycle?.onClose ?? []) dispatch(id);\n    };\n  }, [dispatch, cycle]);\n  return null;\n}\n\nexport function AirHeader({ screen, blockId }: BlockRef) {\n  const visible = useBlockVisible(screen, blockId);\n  const b = block(screen, blockId);\n  // Props SURCHARGÉES par les sorties des slots liés (1.3.0, D-058).\n  const props = useBlockProps(screen, blockId);\n  if (!visible) return null;\n  const title = str(props.title);\n  if (title === undefined) throw new Error(`AIR_RUNTIME_PROP_MISSING:${blockId}:title`);\n  return <HeaderBlock testID={b.id} title={title} subtitle={str(props.subtitle)} />;\n}\n\nexport function AirButton({ screen, blockId }: BlockRef) {\n  const visible = useBlockVisible(screen, blockId);\n  const b = block(screen, blockId);\n  // Props SURCHARGÉES par les sorties des slots liés (1.3.0, D-058).\n  const props = useBlockProps(screen, blockId);\n  const dispatch = useDispatch(screen);\n  if (!visible) return null;\n  const label = str(props.label);\n  const actionId = str(props.actionId);\n  if (label === undefined || actionId === undefined) {\n    throw new Error(`AIR_RUNTIME_PROP_MISSING:${blockId}:label|actionId`);\n  }\n  const kind = props.kind === \"ghost\" ? (\"ghost\" as const) : (\"primary\" as const);\n  // AFFORDANCE (D-084) — un effet `slot` est calculé AU RENDU, jamais sur un\n  // appui : le dispatcher n'a aucune branche pour lui. Un bouton « Appliquer les\n  // filtres » câblé sur un slot était donc PRESSABLE ET MUET. Mesuré sur les\n  // 26 applications : c'est l'une des deux causes des 201 contrôles fantômes.\n  // On ne fabrique aucun comportement — on retire une promesse que rien ne\n  // fonde. Exactement le remède d'`APP-D002`, appliqué à un second effet.\n  const effet = screen.actions[actionId]?.kind;\n  const inerte = effet === \"slot\";\n  return (\n    <ButtonBlock\n      testID={b.id}\n      label={label}\n      kind={kind}\n      onPress={inerte ? undefined : () => dispatch(actionId)}\n    />\n  );\n}\n\nexport function AirEmptyState({ screen, blockId }: BlockRef) {\n  const visible = useBlockVisible(screen, blockId);\n  const b = block(screen, blockId);\n  // Props SURCHARGÉES par les sorties des slots liés (1.3.0, D-058).\n  const props = useBlockProps(screen, blockId);\n  const dispatch = useDispatch(screen);\n  if (!visible) return null;\n  const title = str(props.title);\n  if (title === undefined) throw new Error(`AIR_RUNTIME_PROP_MISSING:${blockId}:title`);\n  const actionId = str(props.actionId);\n  return (\n    <EmptyStateBlock\n      testID={b.id}\n      title={title}\n      message={str(props.message)}\n      actionLabel={str(props.actionLabel)}\n      onAction={actionId === undefined ? undefined : () => dispatch(actionId)}\n    />\n  );\n}\n\nexport function AirDetailHeader({\n  screen,\n  blockId,\n  itemId,\n}: BlockRef & { itemId?: string }) {\n  const visible = useBlockVisible(screen, blockId);\n  const b = block(screen, blockId);\n  // Props SURCHARGÉES par les sorties des slots liés (1.3.0, D-058).\n  const props = useBlockProps(screen, blockId);\n  const provider = useDataProvider();\n  const statut = useDataStatus(b.entityId);\n  const resoudre = useResolveField(screen, b.entityId);\n  if (!visible) return null;\n  if (b.entityId === undefined) throw new Error(`AIR_RUNTIME_ENTITY_MISSING:${blockId}`);\n  const instance = provider.getInstance(b.entityId, itemId);\n  // États du registre 1.1.0 (D-060) — rendus seulement si le titre est DÉCLARÉ.\n  const loadingTitle = str(props.loadingTitle);\n  const errorTitle = str(props.errorTitle);\n  const emptyTitle = str(props.emptyTitle);\n  const etat =\n    statut === \"loading\" && loadingTitle !== undefined\n      ? ({ kind: \"loading\", title: loadingTitle } as const)\n      : statut === \"error\" && errorTitle !== undefined\n        ? ({ kind: \"error\", title: errorTitle, message: str(props.errorMessage) } as const)\n        : instance === undefined && emptyTitle !== undefined\n          ? ({ kind: \"empty\", title: emptyTitle, message: str(props.emptyMessage) } as const)\n          : ({ kind: \"ready\" } as const);\n  const value = (fieldId: unknown): string =>\n    typeof fieldId === \"string\"\n      ? (resoudre(fieldId, instance?.values[fieldId]) ?? \"\")\n      : \"\";\n  const badgeIds = Array.isArray(props.badgeFieldIds) ? props.badgeFieldIds : undefined;\n  return (\n    <DetailHeaderBlock\n      testID={b.id}\n      state={etat}\n      {...(str(props.imageFieldId) !== undefined &&\n      value(props.imageFieldId) !== \"\"\n        ? { imageUri: value(props.imageFieldId) }\n        : {})}\n      title={value(props.titleFieldId)}\n      subtitle={\n        props.subtitleFieldId === undefined ? undefined : value(props.subtitleFieldId)\n      }\n      // D-076 : un badge VIDE n'est pas un badge — il rendait une pastille sans\n      // texte et provoquait une collision de clés. On ne rend que les valeurs\n      // réellement présentes ; `undefined` si aucune ne l'est.\n      badges={\n        badgeIds === undefined\n          ? undefined\n          : (() => {\n              const v = badgeIds.map((id) => value(id)).filter((x) => x !== \"\");\n              return v.length === 0 ? undefined : v;\n            })()\n      }\n      trailing={\n        props.trailingFieldId === undefined ? undefined : value(props.trailingFieldId)\n      }\n    />\n  );\n}\n\nexport function AirList({ screen, blockId, itemId }: BlockRef & { itemId?: string }) {\n  const visible = useBlockVisible(screen, blockId);\n  const b = block(screen, blockId);\n  // Props SURCHARGÉES par les sorties des slots liés (1.3.0, D-058).\n  const props = useBlockProps(screen, blockId);\n  const provider = useDataProvider();\n  const statut = useDataStatus(b.entityId);\n  const resoudre = useResolveField(screen, b.entityId);\n  // Saisie de recherche — LOCALE à la liste : chercher dans un catalogue n'est\n  // pas un état d'application, et le partager entre écrans surprendrait.\n  const [recherche, setRecherche] = useState(\"\");\n  // E1 (D-129) — saisies des filtres PILOTÉS, locales à la liste comme la\n  // recherche. Une valeur vide = filtre inactif.\n  const [saisiesFiltres, setSaisiesFiltres] = useState<Readonly<Record<number, string>>>({});\n  const onItemNavigate = useItemNavigate(screen, blockId);\n  if (!visible) return null;\n  if (b.entityId === undefined) throw new Error(`AIR_RUNTIME_ENTITY_MISSING:${blockId}`);\n  const titleFieldId = str(props.titleFieldId);\n  if (titleFieldId === undefined) {\n    throw new Error(`AIR_RUNTIME_PROP_MISSING:${blockId}:titleFieldId`);\n  }\n  // E1/E2 (D-129) — TRI / FILTRES / PAGINATION / PORTÉE : la vérité vit dans\n  // `lignesVisibles` (module pur, testé sans rendu). Ici : lire les props,\n  // tenir les saisies, déléguer.\n  const brutes0 = provider.listInstances(b.entityId);\n  const rechercheChamp = str(props.searchFieldId);\n  const filtreChamp = str(props.filterFieldId);\n  const filtreValeur = str(props.filterValue);\n  const champsPilotes = strArray(props.userFilterFieldIds);\n  const operateursPilotes = strArray(props.userFilterOperators);\n  const typesPilotes = strArray(props.userFilterInputTypes);\n  const filtres: FiltreEffectif[] = [\n    ...(filtreChamp !== undefined && filtreValeur !== undefined\n      ? [{\n          fieldId: filtreChamp,\n          operator: (str(props.filterOperator) ?? \"eq\") as OperateurFiltre,\n          valeur: filtreValeur,\n        }]\n      : []),\n    ...champsPilotes.map((fieldId, i) => ({\n      fieldId,\n      operator: (operateursPilotes[i] ?? \"eq\") as OperateurFiltre,\n      valeur: saisiesFiltres[i] ?? \"\",\n    })),\n  ];\n  const scopeChamp = str(props.scopeFieldId);\n  const instances = lignesVisibles(brutes0, {\n    scopeFieldId: scopeChamp,\n    instanceId: itemId,\n    rechercheChamp,\n    recherche,\n    filtres,\n    triChamp: str(props.sortFieldId),\n    triDesc: props.sortDirection === \"desc\",\n    borne: typeof props.pageSize === \"number\" ? props.pageSize : undefined,\n  });\n  // Options des filtres `choice` — valeurs distinctes du PÉRIMÈTRE scopé,\n  // jamais du dataset entier d'un autre parent.\n  const scopees =\n    scopeChamp === undefined\n      ? brutes0\n      : itemId === undefined\n        ? []\n        : brutes0.filter((i) => (i.values[scopeChamp] ?? \"\") === itemId);\n  // DET-032 : le TITRE d'un filtre est le libellé déclaré du champ — `name`\n  // (identifiant machine) ne sert que de repli 1.9.0.\n  const champsEntite = screen.entities[b.entityId]?.fields ?? [];\n  const nomsChamps = new Map(champsEntite.map((f) => [f.id, f.label ?? f.name]));\n  const enumLabelsParChamp = new Map(champsEntite.map((f) => [f.id, f.enumLabels]));\n  const filtresSpec =\n    champsPilotes.length === 0\n      ? undefined\n      : champsPilotes.map((fieldId, i) => ({\n          label: nomsChamps.get(fieldId) ?? fieldId,\n          value: saisiesFiltres[i] ?? \"\",\n          onChange: (v: string) =>\n            setSaisiesFiltres((s) => ({ ...s, [i]: v })),\n          inputType: (typesPilotes[i] === \"choice\" ? \"choice\" : \"text\") as \"text\" | \"choice\",\n          ...(typesPilotes[i] === \"choice\"\n            ? {\n                options: optionsDistinctes(scopees, fieldId),\n                // DET-032 — les chips affichent le libellé, filtrent la valeur.\n                ...(enumLabelsParChamp.get(fieldId) === undefined\n                  ? {}\n                  : { optionLabels: enumLabelsParChamp.get(fieldId) }),\n              }\n            : {}),\n        }));\n  const pick = (fieldId: unknown, values: Readonly<Record<string, string>>) =>\n    typeof fieldId === \"string\" ? resoudre(fieldId, values[fieldId]) : undefined;\n  const imageFieldId = str(props.imageFieldId);\n  const items: ListItemData[] = instances.map((instance) => ({\n    id: instance.id,\n    // VIGNETTE (D-087) — seulement si le document a DÉCLARÉ quel champ porter.\n    // Une valeur vide n'est pas une image : on n'en rend aucune.\n    ...(imageFieldId !== undefined && (instance.values[imageFieldId] ?? \"\") !== \"\"\n      ? { imageUri: instance.values[imageFieldId] }\n      : {}),\n    title: resoudre(titleFieldId, instance.values[titleFieldId]) ?? \"\",\n    subtitle: pick(props.subtitleFieldId, instance.values),\n    trailing: pick(props.trailingFieldId, instance.values),\n    badge: pick(props.badgeFieldId, instance.values),\n  }));\n  const emptyTitle = str(props.emptyTitle);\n  const loadingTitle = str(props.loadingTitle);\n  const errorTitle = str(props.errorTitle);\n  const state =\n    statut === \"loading\" && loadingTitle !== undefined\n      ? ({ kind: \"loading\", title: loadingTitle } as const)\n      : statut === \"error\" && errorTitle !== undefined\n        ? ({ kind: \"error\", title: errorTitle, message: str(props.errorMessage) } as const)\n        : items.length === 0 && emptyTitle !== undefined\n          ? ({ kind: \"empty\", title: emptyTitle, message: str(props.emptyMessage) } as const)\n          : ({ kind: \"ready\" } as const);\n  return (\n    <ListBlock\n      testID={b.id}\n      title={str(props.title)}\n      items={items}\n      state={state}\n      // RECHERCHE (D-087) — rendue EN TÊTE de la liste, donc en haut de l'écran\n      // de catalogue. Filtre client sur le champ DÉCLARÉ par le document.\n      search={\n        rechercheChamp === undefined\n          ? undefined\n          : { value: recherche, onChange: setRecherche, placeholder: str(props.searchPlaceholder) }\n      }\n      filters={filtresSpec}\n      onItemPress={onItemNavigate}\n    />\n  );\n}\n\nexport function AirForm({ screen, blockId }: BlockRef) {\n  const visible = useBlockVisible(screen, blockId);\n  const b = block(screen, blockId);\n  // Props SURCHARGÉES par les sorties des slots liés (1.3.0, D-058).\n  const props = useBlockProps(screen, blockId);\n  const dispatch = useDispatch(screen);\n  const statut = useDataStatus(b.entityId);\n  // D-066 : l'état vit AU-DESSUS des écrans. Un retour en arrière ne vide plus\n  // le formulaire — défaut mesuré sur le parcours de commande.\n  const [values, changer] = useFormValues(blockId);\n  if (!visible) return null;\n  if (b.entityId === undefined) throw new Error(`AIR_RUNTIME_ENTITY_MISSING:${blockId}`);\n  const fieldsById = new Map(\n    (screen.entities[b.entityId]?.fields ?? []).map((f) => [f.id, f]),\n  );\n  const fieldIds = Array.isArray(props.fieldIds) ? props.fieldIds : [];\n  // DET-032 (AIR 1.10.0) : le libellé rendu est celui que le document DÉCLARE\n  // (`field.label`, résolu par le compilateur) ; `field.name` reste le repli\n  // 1.9.0 — donnée AIR dans les deux cas, jamais un texte moteur (D-028/F3).\n  const fields: FormFieldSpec[] = fieldIds.flatMap((fieldId) => {\n    if (typeof fieldId !== \"string\") return [];\n    const field = fieldsById.get(fieldId);\n    return field === undefined ? [] : [{ id: field.id, label: field.label ?? field.name }];\n  });\n  const submitLabel = str(props.submitLabel);\n  if (submitLabel === undefined) {\n    throw new Error(`AIR_RUNTIME_PROP_MISSING:${blockId}:submitLabel`);\n  }\n  const actionId = screen.uiActionsByBlock[blockId];\n  return (\n    <FormBlock\n      testID={b.id}\n      title={str(props.title)}\n      fields={fields}\n      values={values}\n      onChangeField={changer}\n      submitLabel={submitLabel}\n      // D-061 : les valeurs SAISIES accompagnent l'action — sans elles, une\n      // création écrirait un enregistrement vide.\n      onSubmit={() => dispatch(actionId, values)}\n      // États du registre 1.1.0 (D-060) : `loading` et `error` deviennent\n      // atteignables dès que la source les rapporte ET que le titre est déclaré.\n      // `empty` pour un formulaire = AUCUN champ à saisir. État réel, pas une\n      // commodité : un formulaire sans champ rendu vide serait un écran muet.\n      state={\n        statut === \"loading\" || statut === \"error\"\n          ? statut\n          : fields.length === 0 && str(props.emptyTitle) !== undefined\n            ? \"empty\"\n            : \"ready\"\n      }\n      loadingTitle={str(props.loadingTitle)}\n      emptyTitle={str(props.emptyTitle)}\n      errorMessage={str(props.errorMessage)}\n    />\n  );\n}\n",
  "lib/runtime/capabilites-auth.ts": "// RUNTIME COPIÉ — FOURNISSEUR DE CAPABILITIES POUR `auth` (Phase 4).\n//\n// Première capability du registre gelé dont la déclaration produit RÉELLEMENT\n// du code dans l'app émise. Les autres restent sans effet : ce fournisseur\n// n'honore QUE `auth`, et REFUSE tout le reste — il ne devient pas un\n// fourre-tout qui prétendrait implémenter ce qu'il n'implémente pas.\n//\n// Méthodes honorées : `signIn` (paramètre `identifiant`) et `signOut`.\n// Toute autre méthode d'`auth` est refusée et tracée, comme le défaut.\nimport type { CapabilityCall, CapabilityProvider } from \"./capability-provider\";\nimport type { SessionLocale } from \"./session-locale\";\n\nexport function creerCapabilitesAuth(session: SessionLocale): CapabilityProvider {\n  return {\n    invoke: (call: CapabilityCall): boolean => {\n      if (call.capability !== \"auth\") {\n        // Code, jamais texte naturel (F3) — module de runtime moteur.\n        console.warn(`AIR_CAPABILITY_NOT_IMPLEMENTED:${call.capability}.${call.method}`);\n        return false;\n      }\n      if (call.method === \"signOut\") {\n        session.fermer();\n        return true;\n      }\n      if (call.method === \"signUp\") {\n        // DOUBLURE FERMÉE (jugement propriétaire) : `signUp` n'était qu'un\n        // alias de `signIn` — « Créer mon compte » ouvrait une session sans\n        // rien créer, promesse morte. Sur une session LOCALE, créer et ouvrir\n        // sont indissociables (aucun serveur ne tient de registre) : le\n        // fournisseur le DIT au lieu de le masquer, et le distingue quand\n        // même par son code de trace. Sur une session VÉRIFIÉE\n        // (`session-supabase`), ce sont deux appels serveur différents.\n        console.warn(\"AIR_CAPABILITY_AUTH_SIGNUP_LOCAL_EQUALS_SIGNIN\");\n      }\n      if (call.method === \"signIn\" || call.method === \"signUp\") {\n        // Le document DÉCLARE quel champ porte l'identité (`identifiantFieldId`)\n        // — deviner « le premier champ e-mail » serait une convention, donc une\n        // supposition. Sans déclaration, rien n'est établi : on refuse.\n        const champ = call.params.identifiantFieldId;\n        if (typeof champ !== \"string\") {\n          console.warn(\"AIR_CAPABILITY_AUTH_IDENTIFIANT_FIELD_MISSING\");\n          return false;\n        }\n        const brut = call.params[champ];\n        return typeof brut === \"string\" && session.ouvrir(brut);\n      }\n      console.warn(`AIR_CAPABILITY_NOT_IMPLEMENTED:${call.capability}.${call.method}`);\n      return false;\n    },\n  };\n}\n",
  "lib/runtime/capability-provider.tsx": "// RUNTIME COPIÉ — CONTRAT D'INVOCATION DES CAPABILITIES (D-059).\n//\n// État mesuré au 2026-08-31 : `capabilitiesEmitCode: false`. Les 15 capabilities\n// du registre gelé ne produisent AUCUNE ligne dans l'app émise, et le\n// dispatcher IGNORE silencieusement un effet `capability`. Sur 152 promesses\n// mortes du corpus, **61 visaient une capability** — le premier tueur.\n//\n// Ce module pose la COUTURE, sur le patron exact du fournisseur de données :\n// le code généré ne dépend jamais d'une implémentation concrète.\n//\n// 🔴 CE QU'IL NE FAIT PAS, ET POURQUOI : il n'implémente aucune capability.\n// Chacune exige son paquet npm (`expo-sharing`, `expo-location`…), or l'app\n// émise embarque un `package-lock.json` de 504 paquets et s'installe avec\n// `npm ci` — qui ÉCHOUE si le lock et le manifeste divergent. Livrer une\n// implémentation exige donc d'étendre le lock EMBARQUÉ du moteur : décision\n// propriétaire, elle fait grandir le train de release (D-059).\n//\n// Le défaut n'est donc PAS une implémentation : c'est un JOURNAL. Une\n// capability non implémentée devient VISIBLE au lieu d'être avalée.\nimport { createContext, useContext } from \"react\";\nimport type { PropsWithChildren } from \"react\";\n\nexport interface CapabilityCall {\n  capability: string;\n  method: string;\n  params: Readonly<Record<string, unknown>>;\n}\n\nexport interface CapabilityProvider {\n  /** `true` si l'appel a été HONORÉ. `false` = non implémentée, jamais un mensonge. */\n  invoke(call: CapabilityCall): boolean;\n}\n\n/**\n * Défaut : refuse et TRACE. Ne prétend jamais avoir agi.\n *\n * Le contraire — retourner `true` en silence — est exactement le défaut\n * `APP-D002` : une promesse que rien ne fonde.\n */\nexport const REPORTING_CAPABILITY_PROVIDER: CapabilityProvider = {\n  invoke: (call) => {\n    // Code, jamais texte naturel (F3) : ce module est du runtime moteur.\n    console.warn(`AIR_CAPABILITY_NOT_IMPLEMENTED:${call.capability}.${call.method}`);\n    return false;\n  },\n};\n\nconst CapabilityContext = createContext<CapabilityProvider>(REPORTING_CAPABILITY_PROVIDER);\n\nexport function CapabilityRoot({\n  provider,\n  children,\n}: PropsWithChildren<{ provider: CapabilityProvider }>) {\n  return (\n    <CapabilityContext.Provider value={provider}>{children}</CapabilityContext.Provider>\n  );\n}\n\nexport function useCapabilityProvider(): CapabilityProvider {\n  return useContext(CapabilityContext);\n}\n",
  "lib/runtime/data-provider.tsx": "// RUNTIME COPIÉ (compilateur 4.3, D-026 S2/§15) — INTERFACE de données du\n// projet généré. Contrat obligatoire dès le premier provider : le code\n// généré ne dépend JAMAIS d'un provider concret. Implémentation par\n// défaut : VIDE (déterministe). L'implémentation `demo` (fixtures\n// déterministes seedées par contentHash) arrive en 4.5 ; Supabase en\n// Phase 5 — sans changement de cette interface.\n// Ce fichier est un ARTEFACT DE SORTIE du compilateur (copie régénérable,\n// D-007) : jamais édité dans un projet généré.\nimport { createContext, useContext, useMemo, useSyncExternalStore } from \"react\";\nimport type { PropsWithChildren } from \"react\";\n// E3.1 (D-130) — le contrat du magasin vit dans son module PUR ; ici on ne\n// fait qu'en importer le TYPE (le cliquet d'exactitude de l'interface\n// DataProvider ne doit voir que les opérations de données déclarées).\nimport type { MagasinDonnees } from \"./magasin-donnees\";\n\nexport interface EntityInstance {\n  id: string;\n  values: Readonly<Record<string, string>>;\n}\n\nexport type DataStatus = \"loading\" | \"ready\" | \"error\";\n\nexport interface DataProvider {\n  listInstances(entityId: string): readonly EntityInstance[];\n  getInstance(entityId: string, instanceId?: string): EntityInstance | undefined;\n  /**\n   * ÉTAT DE LA SOURCE (1.1.0, D-060) — OPTIONNEL.\n   *\n   * Sans lui, les données sont immédiates et le comportement est celui de\n   * 1.0.0, au caractère près. Avec lui, `loading` et `error` deviennent\n   * ATTEIGNABLES : le bloc les rend, à condition que le document ait déclaré\n   * leurs titres (F3 — le moteur n'invente aucun texte).\n   *\n   * Fait qui a rendu ce champ nécessaire : le fournisseur était PUREMENT\n   * SYNCHRONE, donc `loading` était l'état d'une attente qui n'existait pas et\n   * `error` celui d'un appel qui ne pouvait pas échouer. La dimension C d'A++\n   * n'était pas non atteinte — elle était inatteignable (APP-D003).\n   */\n  status?(entityId: string): DataStatus;\n  /**\n   * ÉCRITURE (1.2.0, D-061) — OPTIONNELLE.\n   *\n   * Sans elle, une action `mutation` reste une non-opération et le moteur le\n   * DIT (l'enveloppe le déclare, la gate de fidélité compte la promesse morte).\n   * Avec elle, un bouton « Commander » commande réellement.\n   *\n   * Retourne `true` si l'écriture a été HONORÉE. Jamais un `void` optimiste :\n   * un appelant doit pouvoir distinguer « écrit » de « refusé », sinon on\n   * recrée `APP-D002` — une promesse que rien ne fonde.\n   */\n  create?(entityId: string, values: Readonly<Record<string, string>>): boolean;\n  update?(entityId: string, instanceId: string, values: Readonly<Record<string, string>>): boolean;\n  remove?(entityId: string, instanceId: string): boolean;\n}\n\nexport const EMPTY_DATA_PROVIDER: DataProvider = {\n  listInstances: () => [],\n  getInstance: () => undefined,\n};\n\nconst DataContext = createContext<DataProvider>(EMPTY_DATA_PROVIDER);\n\n/**\n * OBSERVATION (E3.1, D-130) — ADDITIVE. Un provider qui expose `abonner` +\n * `versionGlobale` (le magasin observable) fait re-rendre le sous-arbre à\n * CHAQUE évolution réelle de ses données ; un provider ordinaire garde le\n * comportement historique au caractère près. La granularité anti-tempête est\n * dans le magasin (une évolution sans changement ne notifie pas) — ici on ne\n * fait qu'écouter.\n */\nconst estObservable = (p: DataProvider): p is DataProvider & MagasinDonnees =>\n  typeof (p as Partial<MagasinDonnees>).abonner === \"function\" &&\n  typeof (p as Partial<MagasinDonnees>).versionGlobale === \"function\";\n\nfunction ObservationRoot({\n  provider,\n  children,\n}: PropsWithChildren<{ provider: DataProvider & MagasinDonnees }>) {\n  const version = useSyncExternalStore(\n    provider.abonner,\n    provider.versionGlobale,\n    provider.versionGlobale,\n  );\n  // CAUSE RACINE DÉMONTRÉE (E3.1) : re-rendre ce composant ne re-rend PAS le\n  // sous-arbre — `children` est le MÊME élément (bail-out React), et un\n  // provider d'identité stable ne propage rien par le contexte. La VALEUR du\n  // contexte change donc d'identité à CHAQUE version réelle : chaque\n  // consommateur (`useDataProvider`) re-rend, et lit des données à jour.\n  const valeur = useMemo<DataProvider>(() => ({ ...provider }), [provider, version]);\n  return <DataContext.Provider value={valeur}>{children}</DataContext.Provider>;\n}\n\nexport function DataRoot({\n  provider,\n  children,\n}: PropsWithChildren<{ provider: DataProvider }>) {\n  return estObservable(provider) ? (\n    <ObservationRoot provider={provider}>{children}</ObservationRoot>\n  ) : (\n    <DataContext.Provider value={provider}>{children}</DataContext.Provider>\n  );\n}\n\nexport function useDataProvider(): DataProvider {\n  return useContext(DataContext);\n}\n",
  "lib/runtime/demo-provider.ts": "// RUNTIME COPIÉ (compilateur 4.5, D-026 S2/D-030) — provider `demo` :\n// les lignes de démonstration sont GÉNÉRÉES À LA COMPILATION (module\n// canonique demo.data.ts, fonction pure seedée par le contentHash du\n// dataset — D-013 : preview = données de démo uniquement) ; ce module ne\n// fait que les SERVIR derrière l'interface DataProvider (§15). Instance\n// par défaut d'un écran de détail sans paramètre = PREMIÈRE ligne\n// (déterministe, lecture D-030).\nimport type { DataProvider, EntityInstance } from \"./data-provider\";\n\nexport type DemoData = Readonly<Record<string, readonly EntityInstance[]>>;\n\nexport function buildDemoProvider(data: DemoData): DataProvider {\n  return {\n    listInstances: (entityId) => data[entityId] ?? [],\n    getInstance: (entityId, instanceId) => {\n      const rows = data[entityId] ?? [];\n      if (instanceId === undefined) return rows[0];\n      return rows.find((r) => r.id === instanceId);\n    },\n  };\n}\n",
  "lib/runtime/form-state.tsx": "// RUNTIME COPIÉ — ÉTAT DE FORMULAIRE PARTAGÉ (D-066).\n//\n// `crossScreenFormState: false` : `useState` vivait DANS le composant. Un\n// utilisateur qui remplissait ses coordonnées, revenait en arrière pour vérifier\n// le panier, puis repartait — **retrouvait un formulaire vide**. Sur un parcours\n// de commande, c'est l'abandon garanti.\n//\n// L'état est désormais tenu au-dessus des écrans, indexé par identifiant de\n// bloc. Défaut : un magasin ÉPHÉMÈRE en mémoire, créé à la racine de l'app —\n// donc partagé entre écrans, et remis à zéro au redémarrage. Aucune persistance\n// disque n'est promise : ce serait une capability, et elle n'en est pas une.\nimport { createContext, useCallback, useContext, useMemo, useState } from \"react\";\nimport type { PropsWithChildren } from \"react\";\n\nexport type FormValues = Readonly<Record<string, string>>;\n\nexport interface FormStore {\n  read(blockId: string): FormValues;\n  /** Fusion de tous les formulaires — pour une action portée par un BOUTON. */\n  readAll(): FormValues;\n  write(blockId: string, values: FormValues): void;\n}\n\n/** Magasin INERTE : chaque lecture rend le vide. Comportement d'avant D-066. */\nexport const EMPTY_FORM_STORE: FormStore = {\n  read: () => ({}),\n  readAll: () => ({}),\n  write: () => undefined,\n};\n\nconst FormContext = createContext<FormStore>(EMPTY_FORM_STORE);\n\nexport function FormStateRoot({ children }: PropsWithChildren) {\n  // DÉFAUT CORRIGÉ (D-071) — la première version tenait le magasin dans un\n  // `useRef`. Elle partageait bien l'état entre écrans, mais **aucune écriture\n  // ne provoquait de rendu** : ce que l'utilisateur tapait ne s'affichait pas,\n  // et la soumission envoyait les valeurs du rendu PRÉCÉDENT, donc vides.\n  // Trouvé en pressant réellement le formulaire, pas en relisant le code.\n  const [magasin, setMagasin] = useState<Record<string, FormValues>>({});\n  const store = useMemo<FormStore>(\n    () => ({\n      read: (blockId) => magasin[blockId] ?? {},\n      readAll: () => Object.assign({}, ...Object.values(magasin)) as FormValues,\n      write: (blockId, values) => {\n        setMagasin((prec) => ({ ...prec, [blockId]: values }));\n      },\n    }),\n    [magasin],\n  );\n  return <FormContext.Provider value={store}>{children}</FormContext.Provider>;\n}\n\n/**\n * Valeurs saisies dans TOUS les formulaires montés (D-083).\n *\n * Défaut trouvé en pressant l'application réellement envoyée : les documents\n * générés câblent la mutation sur un BOUTON, pas sur le formulaire — c'est même\n * la forme la plus naturelle (« Valider » est un bouton). Or l'état vivait\n * strictement par bloc : le bouton n'avait accès à RIEN. L'utilisateur\n * remplissait, appuyait, et la règle de validation refusait une saisie vide.\n * **Silencieusement.** Exactement la famille de défaut que ce chantier traque.\n */\nexport function useAllFormValues(): FormValues {\n  const store = useContext(FormContext);\n  return store.readAll();\n}\n\nexport function useFormValues(\n  blockId: string,\n): [FormValues, (fieldId: string, value: string) => void] {\n  const store = useContext(FormContext);\n  const valeurs = store.read(blockId);\n  const ecrire = useCallback(\n    (fieldId: string, value: string) => {\n      store.write(blockId, { ...store.read(blockId), [fieldId]: value });\n    },\n    [store, blockId],\n  );\n  return [valeurs, ecrire];\n}\n",
  "lib/runtime/list-pipeline.ts": "// PIPELINE DE LIGNES D'UNE LISTE (E1/E2, D-129) — module PUR, zéro import.\n//\n// POURQUOI UN MODULE SÉPARÉ : la logique de visibilité des lignes doit être\n// PROUVABLE par tests unitaires sans monter react-native. `AirList` ne fait\n// plus que tenir les états de saisie et déléguer ici — le composant reste\n// mince, la vérité est testable.\n//\n// ORDRE VOLONTAIRE (D-065 étendu) : périmètre relationnel (E2), puis\n// recherche, puis filtres (littéral + pilotés, CONJONCTION), puis tri, puis\n// borne. Fermé par construction : trois opérateurs, une direction, une borne,\n// au plus trois filtres — aucune expression arbitraire n'entre jamais.\n\nexport interface LigneListe {\n  readonly id: string;\n  readonly values: Readonly<Record<string, string>>;\n}\n\nexport type OperateurFiltre = \"eq\" | \"neq\" | \"contains\";\n\nexport interface FiltreEffectif {\n  readonly fieldId: string;\n  readonly operator: OperateurFiltre;\n  /** Valeur du document (littéral) ou saisie de l'utilisateur (piloté). */\n  readonly valeur: string;\n}\n\nexport interface ParametresPipeline {\n  /**\n   * E2 — PORTÉE RELATIONNELLE. Si `scopeFieldId` est déclaré, seules les\n   * lignes dont ce champ vaut `instanceId` sont visibles. SANS instance\n   * courante, une liste scopée est VIDE — jamais de repli silencieux vers un\n   * autre parent (la classe « premier enregistrement en silence » ne doit pas\n   * renaître ici ; D-129).\n   */\n  readonly scopeFieldId?: string;\n  readonly instanceId?: string;\n  readonly rechercheChamp?: string;\n  readonly recherche?: string;\n  /** Filtres effectifs, littéral inclus — un filtre à valeur vide est INACTIF. */\n  readonly filtres?: readonly FiltreEffectif[];\n  readonly triChamp?: string;\n  readonly triDesc?: boolean;\n  readonly borne?: number;\n}\n\nconst passeFiltre = (v: string, f: FiltreEffectif): boolean =>\n  f.operator === \"neq\" ? v !== f.valeur : f.operator === \"contains\" ? v.includes(f.valeur) : v === f.valeur;\n\nexport function lignesVisibles(\n  instances: readonly LigneListe[],\n  p: ParametresPipeline,\n): readonly LigneListe[] {\n  const scopees =\n    p.scopeFieldId === undefined\n      ? instances\n      : p.instanceId === undefined\n        ? []\n        : instances.filter((i) => (i.values[p.scopeFieldId as string] ?? \"\") === p.instanceId);\n  const saisie = (p.recherche ?? \"\").trim().toLowerCase();\n  const cherchees =\n    p.rechercheChamp === undefined || saisie === \"\"\n      ? scopees\n      : scopees.filter((i) =>\n          (i.values[p.rechercheChamp as string] ?? \"\").toLowerCase().includes(saisie),\n        );\n  const actifs = (p.filtres ?? []).filter((f) => f.valeur !== \"\");\n  const filtrees = actifs.reduce(\n    (lignes, f) => lignes.filter((i) => passeFiltre(i.values[f.fieldId] ?? \"\", f)),\n    cherchees,\n  );\n  const triees =\n    p.triChamp === undefined\n      ? filtrees\n      : [...filtrees].sort((x, y) => {\n          const a = x.values[p.triChamp as string] ?? \"\";\n          const c = y.values[p.triChamp as string] ?? \"\";\n          const na = Number(a);\n          const nc = Number(c);\n          const ordre = Number.isFinite(na) && Number.isFinite(nc) ? na - nc : a.localeCompare(c);\n          return p.triDesc === true ? -ordre : ordre;\n        });\n  return p.borne === undefined ? triees : triees.slice(0, p.borne);\n}\n\n/** Valeurs distinctes d'un champ sur le périmètre déjà scopé — options `choice`. */\nexport function optionsDistinctes(\n  instances: readonly LigneListe[],\n  fieldId: string,\n): readonly string[] {\n  return [...new Set(instances.map((i) => i.values[fieldId] ?? \"\").filter((v) => v !== \"\"))].sort();\n}\n",
  "lib/runtime/magasin-donnees.ts": "// MAGASIN OBSERVABLE (E3.1, D-130) — module PUR, aucun import react.\n//\n// L'UI continue de LIRE EN SYNCHRONE (le contrat DataProvider est inchangé) :\n// le magasin sert un INSTANTANÉ par entité {rows, status, version}. Ce qui\n// change : l'instantané peut ÉVOLUER — chargement, nouvelles données, erreur,\n// écritures locales — et chaque évolution RÉELLE notifie les abonnés, qui\n// re-rendent. Une évolution qui ne change rien ne notifie PAS (anti-tempête).\n//\n// FRONTIÈRE D'HONNÊTETÉ : ce module ne connaît NI le réseau, NI l'horloge,\n// NI la moindre notion de « live ». Il applique des transitions qu'on lui\n// DONNE — l'adaptateur scripté des bancs les donne en séquence déterministe ;\n// un futur adaptateur (E3.3) les donnera depuis une source déclarée. Un seed\n// sans transitions se comporte au caractère près comme le provider historique.\n//\n// ERREUR : le dernier instantané est CONSERVÉ et l'état passe à `error` — le\n// bloc rend l'état d'erreur avec les titres du document (D-060/F3). Jamais du\n// périmé présenté comme frais : c'est l'ÉTAT qui porte la vérité, pas les\n// lignes.\n// Types STRUCTURAUX locaux — zéro import (module pur, comme `list-pipeline`).\n// Compatibles par FORME avec le contrat `DataProvider` de `data-provider.tsx` :\n// le magasin s'y branche par typage structurel, jamais par héritage nominal.\nexport interface EntityInstance {\n  id: string;\n  values: Readonly<Record<string, string>>;\n}\nexport type DataStatus = \"loading\" | \"ready\" | \"error\";\n\ninterface EtatEntite {\n  rows: readonly EntityInstance[];\n  status: DataStatus;\n  version: number;\n  serie: number;\n}\n\nexport interface MagasinDonnees {\n  listInstances(entityId: string): readonly EntityInstance[];\n  getInstance(entityId: string, instanceId?: string): EntityInstance | undefined;\n  status(entityId: string): DataStatus;\n  create(entityId: string, values: Readonly<Record<string, string>>): boolean;\n  update(entityId: string, instanceId: string, values: Readonly<Record<string, string>>): boolean;\n  remove(entityId: string, instanceId: string): boolean;\n  abonner(ecouteur: () => void): () => void;\n  versionGlobale(): number;\n  versionEntite(entityId: string): number;\n  /** Transition : la source part chercher — les lignes actuelles restent servies. */\n  appliquerChargement(entityId: string): void;\n  /** Transition : données arrivées. IDENTIQUES ⇒ aucun changement, aucune notification. */\n  appliquerDonnees(entityId: string, rows: readonly EntityInstance[]): void;\n  /** Transition : échec. Le dernier instantané est conservé, l'état dit la vérité. */\n  appliquerErreur(entityId: string): void;\n}\n\nconst cloneRows = (rows: readonly EntityInstance[]): readonly EntityInstance[] =>\n  rows.map((r) => ({ id: r.id, values: { ...r.values } }));\n\nexport function creerMagasin(\n  seed: Readonly<Record<string, readonly EntityInstance[]>>,\n): MagasinDonnees {\n  const etats = new Map<string, EtatEntite>();\n  for (const [entityId, rows] of Object.entries(seed)) {\n    etats.set(entityId, { rows: cloneRows(rows), status: \"ready\", version: 0, serie: rows.length });\n  }\n  const etat = (entityId: string): EtatEntite => {\n    const existant = etats.get(entityId);\n    if (existant !== undefined) return existant;\n    const neuf: EtatEntite = { rows: [], status: \"ready\", version: 0, serie: 0 };\n    etats.set(entityId, neuf);\n    return neuf;\n  };\n  let globale = 0;\n  const ecouteurs = new Set<() => void>();\n  const notifier = (e: EtatEntite): void => {\n    e.version += 1;\n    globale += 1;\n    for (const l of [...ecouteurs]) l();\n  };\n  return {\n    // ── Lectures : le contrat historique, au caractère près (repli rows[0]). ──\n    listInstances: (entityId) => etat(entityId).rows,\n    getInstance: (entityId, instanceId) => {\n      const { rows } = etat(entityId);\n      return instanceId === undefined ? rows[0] : rows.find((r) => r.id === instanceId);\n    },\n    status: (entityId) => etat(entityId).status,\n    // ── Écritures locales (D-061) : vérité booléenne, observation réelle. ──\n    create: (entityId, values) => {\n      const e = etat(entityId);\n      e.serie += 1;\n      e.rows = [...e.rows, { id: `${entityId}_l${String(e.serie)}`, values: { ...values } }];\n      notifier(e);\n      return true;\n    },\n    update: (entityId, instanceId, values) => {\n      const e = etat(entityId);\n      const i = e.rows.findIndex((r) => r.id === instanceId);\n      if (i < 0) return false;\n      e.rows = e.rows.map((r, j) => (j === i ? { id: r.id, values: { ...r.values, ...values } } : r));\n      notifier(e);\n      return true;\n    },\n    remove: (entityId, instanceId) => {\n      const e = etat(entityId);\n      const avant = e.rows.length;\n      e.rows = e.rows.filter((r) => r.id !== instanceId);\n      if (e.rows.length === avant) return false;\n      notifier(e);\n      return true;\n    },\n    // ── Observation. ──\n    abonner: (ecouteur) => {\n      ecouteurs.add(ecouteur);\n      return () => ecouteurs.delete(ecouteur);\n    },\n    versionGlobale: () => globale,\n    versionEntite: (entityId) => etat(entityId).version,\n    // ── Transitions de source (données PAR l'appelant — jamais d'horloge ici). ──\n    appliquerChargement: (entityId) => {\n      const e = etat(entityId);\n      if (e.status === \"loading\") return;\n      // DET-033 (jugement propriétaire sur SM-A175F) : une revalidation en\n      // ARRIÈRE-PLAN ne remplace pas des données affichées par un état de\n      // chargement. Le polling repassait chaque écran par « Chargement… »\n      // toutes les 30 s — l'UI clignotait, et le champ de recherche était\n      // démonté en pleine frappe. Tant que des lignes existent, l'instantané\n      // servi reste la vérité (l'erreur, elle, continue de se DIRE — D-060) ;\n      // le chargement VISIBLE reste réservé au tout premier remplissage.\n      if (e.rows.length > 0) return;\n      e.status = \"loading\";\n      notifier(e);\n    },\n    appliquerDonnees: (entityId, rows) => {\n      const e = etat(entityId);\n      const identiques =\n        e.status === \"ready\" && JSON.stringify(e.rows) === JSON.stringify(rows);\n      if (identiques) return; // anti-tempête : rien ne change, rien ne notifie\n      e.rows = cloneRows(rows);\n      e.status = \"ready\";\n      notifier(e);\n    },\n    appliquerErreur: (entityId) => {\n      const e = etat(entityId);\n      if (e.status === \"error\") return;\n      e.status = \"error\"; // les lignes RESTENT — l'état porte la vérité\n      notifier(e);\n    },\n  };\n}\n",
  "lib/runtime/primary-nav.tsx": "// NAVIGATION PRINCIPALE PERSISTANTE — D-086.\n//\n// Fait mesuré sur le corpus v3 : **184 boutons de navigation pure sur 235**,\n// 1,7 par écran, jusqu'à QUATRE empilés sous la liste des plats. Le contrat ne\n// savait pas exprimer une destination principale ; le générateur n'avait donc\n// que le bouton de contenu.\n//\n// 🔴 POURQUOI PAS `createBottomTabNavigator` : ce paquet n'est ni dans le\n// gabarit ni dans le `package-lock` EMBARQUÉ (0 entrée, mesuré). L'ajouter\n// exigerait d'ouvrir le lock de 504 paquets — la même décision que les\n// capabilities. Cette barre n'utilise QUE ce qui est déjà là :\n// `useNavigation` (@react-navigation/native), `Pressable`/`View`/`Text`\n// (react-native), `useSafeAreaInsets` (react-native-safe-area-context).\n//\n// CONTREPARTIE ASSUMÉE : un vrai tab navigator conserve l'historique de chaque\n// onglet ; une pile + barre RE-NAVIGUE. Pour l'utilisateur — persistante,\n// compacte, en bas, toujours visible — le comportement est identique.\nimport { Pressable, Text, View } from \"react-native\";\nimport { useNavigation } from \"@react-navigation/native\";\nimport { useSafeAreaInsets } from \"react-native-safe-area-context\";\nimport Ionicons from \"@expo/vector-icons/Ionicons\";\nimport { useStyles } from \"../primitives/theme-bridge\";\n\n/**\n * TABLE DE CORRESPONDANCE — un rôle déclaré par le document, un glyphe connu\n * du moteur (1.8.0). Elle est FERMÉE et exhaustive : le schéma n'admet que ces\n * onze valeurs, et chacune trouve ici son dessin. Aucune valeur libre, aucune\n * URL, aucun accès réseau — la police d'icônes est embarquée par le paquet.\n */\nconst GLYPHE = {\n  accueil: \"home-outline\",\n  recherche: \"search-outline\",\n  liste: \"list-outline\",\n  billet: \"ticket-outline\",\n  panier: \"cart-outline\",\n  calendrier: \"calendar-outline\",\n  carte: \"map-outline\",\n  compte: \"person-outline\",\n  favoris: \"heart-outline\",\n  message: \"chatbubble-outline\",\n  reglages: \"settings-outline\",\n} as const;\n\nexport type IconeOnglet = keyof typeof GLYPHE;\n\nexport interface PrimaryDestinationData {\n  routeId: string;\n  screenId: string;\n  label: string;\n  order: number;\n  /** Rôle visuel déclaré par le document. Absent ⇒ aucun glyphe, pas de défaut. */\n  icon?: IconeOnglet;\n}\n\nexport interface PrimaryNavProps {\n  destinations: readonly PrimaryDestinationData[];\n  /** Écran courant — pour marquer l'onglet actif, jamais pour le désactiver. */\n  currentScreenId: string;\n}\n\nexport function PrimaryNav({ destinations, currentScreenId }: PrimaryNavProps) {\n  const navigation = useNavigation();\n  const insets = useSafeAreaInsets();\n  const s = useStyles();\n  if (destinations.length === 0) return null;\n  // L'ORDRE déclaré par le document fait foi. Trier ici, et non à l'émission,\n  // garantit que ce qui est RENDU respecte la déclaration même si un étage\n  // intermédiaire réordonnait.\n  const triees = [...destinations].sort((a, b) => a.order - b.order);\n  return (\n    <View\n      testID=\"primary-nav\"\n      style={[s.primaryNav, { paddingBottom: insets.bottom }]}\n      accessibilityRole=\"tablist\"\n    >\n      {triees.map((d) => {\n        const actif = d.screenId === currentScreenId;\n        return (\n          <Pressable\n            key={d.routeId}\n            testID={`primary-nav-${d.routeId}`}\n            accessibilityRole=\"tab\"\n            accessibilityState={{ selected: actif }}\n            style={actif ? s.primaryNavItemActive : s.primaryNavItem}\n            onPress={() => {\n              (navigation.navigate as (name: string) => void)(d.screenId);\n            }}\n          >\n            {/* AUCUNE limite de lignes ici (D-086) — la dimension A++ E l'a\n                refusée, à raison : borner un libellé d'onglet le rend illisible\n                dès que l'utilisateur agrandit le texte système. La barre grandit\n                alors un peu : c'est le comportement attendu, pas un défaut.\n                Le mot exact est volontairement absent — la grille le cherche par\n                sous-chaîne et ne distingue pas un commentaire du code. */}\n            {d.icon === undefined ? null : (\n              <Ionicons\n                name={GLYPHE[d.icon]}\n                size={s.primaryNavIcon.fontSize}\n                color={actif ? s.primaryNavLabelActive.color : s.primaryNavLabel.color}\n              />\n            )}\n            <Text style={actif ? s.primaryNavLabelActive : s.primaryNavLabel}>\n              {d.label}\n            </Text>\n          </Pressable>\n        );\n      })}\n    </View>\n  );\n}\n",
  "lib/runtime/session-contract.ts": "// RUNTIME COPIÉ — CONTRAT DE SESSION, TYPES PURS (Phase 4).\n//\n// Séparé de `session-provider.tsx` parce qu'un module `.ts` ne peut pas\n// importer un module JSX : les implémentations (`session-locale`,\n// `session-supabase`) sont du TypeScript pur et doivent pouvoir dépendre du\n// contrat sans traîner React derrière elles. Le contexte React, lui, vit dans\n// le `.tsx` et RÉ-EXPORTE ce contrat — un seul contrat, deux portes.\nexport interface SessionProvider {\n  /** `true` si une identité est ÉTABLIE. Jamais une supposition. */\n  estAuthentifie(): boolean;\n  /** Identifiant de l'utilisateur courant — absent tant qu'aucune identité. */\n  identifiant(): string | undefined;\n  /** Abonnement aux changements d'état — rend la fonction de désabonnement. */\n  abonner(ecouteur: () => void): () => void;\n}\n",
  "lib/runtime/session-locale.ts": "// RUNTIME COPIÉ — SESSION LOCALE (Phase 4).\n//\n// 🔴 CE QUE C'EST, DIT SANS DÉTOUR : une session tenue EN MÉMOIRE dans\n// l'appareil. Elle établit une identité DÉCLARÉE par la personne, jamais\n// VÉRIFIÉE par un serveur. C'est l'exact équivalent, pour l'identité, de\n// `demo.data.ts` pour les données : le parcours est réel et jugeable, la\n// vérification vient avec l'implémentation distante.\n//\n// Une session VÉRIFIÉE (registre `auth` : Supabase email/OTP) est une autre\n// implémentation du même contrat `SessionProvider`. Elle exige d'étendre le\n// lock EMBARQUÉ du moteur — décision propriétaire (D-059) — et n'est donc\n// pas fournie ici. Le contrat, lui, ne changera pas : c'est tout l'intérêt\n// de la couture.\n//\n// Aucune persistance : quitter l'app déconnecte. Prétendre le contraire\n// exigerait `offline_storage`, capability déclarée mais non implémentée.\nimport type { SessionProvider } from \"./session-contract\";\n\nexport interface SessionLocale extends SessionProvider {\n  /** Établit la session locale. `false` si l'identifiant est vide. */\n  ouvrir(identifiant: string): boolean;\n  /** Termine la session. */\n  fermer(): void;\n}\n\nexport function creerSessionLocale(): SessionLocale {\n  let identite: string | undefined;\n  const ecouteurs = new Set<() => void>();\n  const notifier = (): void => {\n    for (const e of ecouteurs) e();\n  };\n  return {\n    estAuthentifie: () => identite !== undefined,\n    identifiant: () => identite,\n    abonner: (ecouteur) => {\n      ecouteurs.add(ecouteur);\n      return () => {\n        ecouteurs.delete(ecouteur);\n      };\n    },\n    ouvrir: (valeur) => {\n      const propre = valeur.trim();\n      // Une identité VIDE n'est pas une identité — refuser, jamais inventer.\n      if (propre === \"\") return false;\n      if (identite === propre) return true;\n      identite = propre;\n      notifier();\n      return true;\n    },\n    fermer: () => {\n      if (identite === undefined) return;\n      identite = undefined;\n      notifier();\n    },\n  };\n}\n",
  "lib/runtime/session-provider.tsx": "// RUNTIME COPIÉ — CONTRAT DE SESSION (Phase 4).\n//\n// Fait mesuré avant ce module : l'enveloppe concédait « les règles\n// `authorization` ne sont PAS appliquées — elles supposent une identité, que\n// le moteur n'a pas », et `visibleWhen` ne connaissait que des prédicats de\n// DONNÉES. Une app générée ne pouvait donc pas distinguer un visiteur d'un\n// utilisateur connecté : l'authentification était inexprimable AVANT même la\n// question du backend.\n//\n// Ce module pose la COUTURE, sur le patron exact des fournisseurs de données\n// et de capabilities : le code généré ne dépend d'aucune implémentation\n// concrète. Une session RÉELLE (Supabase email/OTP, registre `auth`) est une\n// implémentation de ce contrat — elle exige d'étendre le lock EMBARQUÉ du\n// moteur, décision propriétaire (D-059), et n'est pas fournie ici.\n//\n// 🔴 LE DÉFAUT NE MENT PAS : sans fournisseur, la session est ANONYME. Il ne\n// prétend jamais qu'un utilisateur est connecté — c'est l'équivalent, pour\n// l'identité, du fournisseur de capabilities qui refuse et trace.\nimport { createContext, useContext } from \"react\";\nimport type { PropsWithChildren } from \"react\";\n\nimport type { SessionProvider } from \"./session-contract\";\n\n// Un seul contrat, deux portes : les implémentations pures l'importent depuis\n// `session-contract.ts`, les consommateurs React depuis ici.\nexport type { SessionProvider };\n\n/** Défaut : ANONYME. Aucune identité n'a été établie, et rien ne le prétend. */\nexport const SESSION_ANONYME: SessionProvider = {\n  estAuthentifie: () => false,\n  identifiant: () => undefined,\n  abonner: () => () => undefined,\n};\n\nconst SessionContext = createContext<SessionProvider>(SESSION_ANONYME);\n\nexport function SessionRoot({\n  provider,\n  children,\n}: PropsWithChildren<{ provider: SessionProvider }>) {\n  return <SessionContext.Provider value={provider}>{children}</SessionContext.Provider>;\n}\n\nexport function useSessionProvider(): SessionProvider {\n  return useContext(SessionContext);\n}\n",
  "lib/runtime/session-supabase.ts": "// RUNTIME COPIÉ — SESSION VÉRIFIÉE (Phase 4, extension du lock).\n//\n// Implémentation RÉELLE du contrat `SessionProvider` : l'identité est établie\n// par un serveur, pas déclarée par l'appareil. C'est la différence exacte avec\n// `session-locale.ts`, qui reste le comportement des documents ne déclarant\n// aucune intégration d'authentification.\n//\n// Le CLIENT est INJECTÉ : ce module ne construit aucune connexion et n'impose\n// aucun transport. Les tests l'exercent donc sans réseau — un fournisseur qui\n// ne peut être éprouvé qu'en ligne n'est pas éprouvé.\n//\n// F3 : aucun texte naturel — les diagnostics sont des codes.\nimport type { SessionProvider } from \"./session-contract\";\n\n/** Sous-ensemble EXACT de `@supabase/supabase-js` dont ce module dépend. */\nexport interface ClientAuth {\n  auth: {\n    getSession(): Promise<{ data: { session: { user: { id: string } } | null } }>;\n    signInWithPassword(c: { email: string; password: string }): Promise<{\n      data: { session: { user: { id: string } } | null };\n      error: { message: string } | null;\n    }>;\n    signUp(c: { email: string; password: string }): Promise<{\n      data: { session: { user: { id: string } } | null };\n      error: { message: string } | null;\n    }>;\n    signOut(): Promise<{ error: { message: string } | null }>;\n    onAuthStateChange(\n      cb: (evenement: string, session: { user: { id: string } } | null) => void,\n    ): { data: { subscription: { unsubscribe(): void } } };\n  };\n}\n\nexport interface SessionVerifiee extends SessionProvider {\n  ouvrir(email: string, motDePasse: string): Promise<boolean>;\n  creer(email: string, motDePasse: string): Promise<boolean>;\n  fermer(): Promise<void>;\n}\n\nexport function creerSessionSupabase(client: ClientAuth): SessionVerifiee {\n  let identite: string | undefined;\n  const ecouteurs = new Set<() => void>();\n  const notifier = (): void => {\n    for (const e of ecouteurs) e();\n  };\n  const appliquer = (session: { user: { id: string } } | null): void => {\n    const suivant = session?.user.id;\n    if (suivant === identite) return;\n    identite = suivant;\n    notifier();\n  };\n  // Session DÉJÀ établie (persistée par le client) : on la lit, on ne la\n  // suppose pas. Et on suit les changements décidés par le serveur.\n  void client.auth.getSession().then((r) => {\n    appliquer(r.data.session);\n  });\n  client.auth.onAuthStateChange((_e, session) => {\n    appliquer(session);\n  });\n  return {\n    estAuthentifie: () => identite !== undefined,\n    identifiant: () => identite,\n    abonner: (ecouteur) => {\n      ecouteurs.add(ecouteur);\n      return () => {\n        ecouteurs.delete(ecouteur);\n      };\n    },\n    ouvrir: async (email, motDePasse) => {\n      const r = await client.auth.signInWithPassword({ email, password: motDePasse });\n      if (r.error !== null) {\n        console.warn(`AIR_AUTH_SIGNIN_REFUSED:${r.error.message}`);\n        return false;\n      }\n      appliquer(r.data.session);\n      // Une réponse SANS session n'est pas une connexion — ne jamais le\n      // prétendre (cas réel : confirmation par e-mail exigée).\n      return r.data.session !== null;\n    },\n    creer: async (email, motDePasse) => {\n      const r = await client.auth.signUp({ email, password: motDePasse });\n      if (r.error !== null) {\n        console.warn(`AIR_AUTH_SIGNUP_REFUSED:${r.error.message}`);\n        return false;\n      }\n      appliquer(r.data.session);\n      return true;\n    },\n    fermer: async () => {\n      await client.auth.signOut();\n      appliquer(null);\n    },\n  };\n}\n",
  "lib/runtime/slot-provider.tsx": "// RUNTIME COPIÉ — REGISTRE DE SLOTS du projet généré (D-058).\n//\n// Fait fondateur : le compilateur ÉMETTAIT le code des slots (`slots/*.ts` +\n// `slots/registry.ts`) et l'Oracle en refusait les exfiltrations — mais RIEN NE\n// LES APPELAIT. `slotsInvoked: false`. Sur 152 promesses mortes du corpus,\n// **44 visaient un slot**.\n//\n// Ce module fournit le registre au runtime, sur le patron EXACT du fournisseur\n// de données : le code généré ne dépend jamais d'une implémentation concrète.\n// Défaut : registre VIDE — un slot non fourni n'est pas invoqué, et le bloc\n// garde la prop que le document a déclarée.\nimport { createContext, useContext } from \"react\";\nimport type { PropsWithChildren } from \"react\";\n\n/** Un slot : entrées nommées → sorties nommées. Signature conservée telle quelle. */\nexport type SlotFn = (entrees: Readonly<Record<string, unknown>>) => Readonly<\n  Record<string, unknown>\n>;\n\nexport type SlotRegistry = Readonly<Record<string, SlotFn>>;\n\nexport const EMPTY_SLOT_REGISTRY: SlotRegistry = {};\n\nconst SlotContext = createContext<SlotRegistry>(EMPTY_SLOT_REGISTRY);\n\nexport function SlotRoot({\n  registry,\n  children,\n}: PropsWithChildren<{ registry: SlotRegistry }>) {\n  return <SlotContext.Provider value={registry}>{children}</SlotContext.Provider>;\n}\n\nexport function useSlotRegistry(): SlotRegistry {\n  return useContext(SlotContext);\n}\n",
  "lib/runtime/source-reseau.ts": "// ADAPTATEUR DE SOURCE DISTANTE (E3.3) — générique et SECTOR-AGNOSTIC : il ne\n// connaît que le contrat (cibles résolues par le LOCK, politique de domaines,\n// magasin observable). AUCUNE logique métier, AUCUN secteur.\n//\n// Doctrine :\n//  - FAIL-CLOSED : une cible dont l'URL ne se prouve pas admissible (https,\n//    hôte EXACTEMENT dans la politique, forme saine) n'atteint JAMAIS le\n//    transport — l'état passe en erreur et dit la vérité.\n//  - Le transport est INJECTÉ : l'app émise branche `fetch`, les bancs\n//    injectent un transport déterministe. L'adaptateur ne fabrique aucune\n//    donnée : une réponse hors contrat (forme inattendue) est REFUSÉE.\n//  - Les transitions appartiennent au magasin (E3.1) : chargement → données /\n//    erreur ; l'identique ne notifie pas — l'adaptateur n'invente donc jamais\n//    de « nouveauté ».\n//  - Le rafraîchissement périodique est du POLLING (planificateur injecté,\n//    `refreshSeconds`) — ce n'est PAS du temps réel poussé, et rien ici ne\n//    doit être présenté comme tel.\n//  - Journal APPEND-ONLY sans horloge : la trace est déterministe — mêmes\n//    entrées ⇒ même journal, byte pour byte.\nimport type { EntityInstance, MagasinDonnees } from \"./magasin-donnees\";\n\nexport interface ReponseTransport {\n  readonly ok: boolean;\n  readonly status: number;\n  readonly corps: unknown;\n}\n\n/** Contrat du transport injecté : une URL, une réponse — rien d'autre. */\nexport type Transport = (url: string) => Promise<ReponseTransport>;\n\n/** Planificateur injecté (polling) : rend la fonction d'annulation. */\nexport type Planificateur = (cb: () => void, secondes: number) => () => void;\n\n/** Cible résolue par le LOCK (jamais construite ici — l'adaptateur ne décide\n *  pas des endpoints, il les applique). */\nexport interface CibleRemote {\n  readonly datasetId: string;\n  readonly entityId: string;\n  readonly integrationId: string;\n  readonly url: string;\n  readonly refreshSeconds?: number;\n}\n\nexport interface AdaptateurReseau {\n  /** Charge toutes les cibles admissibles, puis arme le polling déclaré. */\n  demarrer(): Promise<void>;\n  rafraichir(entityId: string): Promise<void>;\n  arreter(): void;\n  /** Trace déterministe des décisions — matière des preuves, jamais du décor. */\n  journal(): readonly string[];\n}\n\n// Hôte d'une URL https SANS port : le port n'est pas exprimable dans\n// `network.allowedDomains` (regex du contrat), donc une URL portée est\n// inadmissible par construction — fail-closed, pas de tolérance.\nconst HOTE_HTTPS = /^https:\\/\\/([a-z0-9]([a-z0-9-]*[a-z0-9])?(\\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+)\\/[^\\s]*$/;\n\nconst estInstance = (x: unknown): x is EntityInstance => {\n  if (typeof x !== \"object\" || x === null) return false;\n  const inst = x as { id?: unknown; values?: unknown };\n  if (typeof inst.id !== \"string\" || inst.id.length === 0) return false;\n  if (typeof inst.values !== \"object\" || inst.values === null) return false;\n  return Object.values(inst.values).every((v) => typeof v === \"string\");\n};\n\nconst lignesValides = (corps: unknown): readonly EntityInstance[] | undefined => {\n  if (!Array.isArray(corps)) return undefined;\n  return corps.every(estInstance) ? (corps as readonly EntityInstance[]) : undefined;\n};\n\n/**\n * Transport APPAREIL par défaut (câblé par l'app émise) : `fetch` global de\n * React Native. SEUL point réseau du runtime — exemption NOMMÉE du cliquet\n * zéro-réseau (D-132) : ce code ne s'exécute JAMAIS pendant la compilation,\n * uniquement dans l'app émise, sur l'appareil, vers des cibles résolues par\n * le lock et revérifiées contre `network.allowedDomains`.\n */\nexport const transportHttp: Transport = async (url) => {\n  const r = await fetch(url);\n  let corps: unknown = null;\n  try {\n    corps = await r.json();\n  } catch {\n    corps = null;\n  }\n  return { ok: r.ok, status: r.status, corps };\n};\n\n/** Planificateur APPAREIL par défaut — POLLING, jamais du temps réel poussé. */\nexport const planificateurIntervalle: Planificateur = (cb, secondes) => {\n  const t = setInterval(cb, secondes * 1000);\n  return () => clearInterval(t);\n};\n\nexport function creerAdaptateurReseau(options: {\n  readonly magasin: MagasinDonnees;\n  readonly cibles: readonly CibleRemote[];\n  readonly domainesAutorises: readonly string[];\n  readonly transport: Transport;\n  readonly planificateur?: Planificateur;\n}): AdaptateurReseau {\n  const { magasin, cibles, domainesAutorises, transport, planificateur } = options;\n  const journal: string[] = [];\n  const annulations: (() => void)[] = [];\n\n  // Admissibilité prouvée UNE fois, AVANT tout transport (fail-closed).\n  const admissibles = new Map<string, CibleRemote>();\n  for (const cible of cibles) {\n    const hote = HOTE_HTTPS.exec(cible.url)?.[1];\n    if (hote === undefined) {\n      journal.push(`refus_url:${cible.entityId}:${cible.url}`);\n      magasin.appliquerErreur(cible.entityId);\n      continue;\n    }\n    if (!domainesAutorises.includes(hote)) {\n      journal.push(`refus_domaine:${cible.entityId}:${hote}`);\n      magasin.appliquerErreur(cible.entityId);\n      continue;\n    }\n    admissibles.set(cible.entityId, cible);\n  }\n\n  const rafraichir = async (entityId: string): Promise<void> => {\n    const cible = admissibles.get(entityId);\n    if (cible === undefined) {\n      journal.push(`refus_cible:${entityId}`);\n      return;\n    }\n    journal.push(`chargement:${entityId}`);\n    magasin.appliquerChargement(entityId);\n    let reponse: ReponseTransport;\n    try {\n      reponse = await transport(cible.url);\n    } catch {\n      journal.push(`erreur_transport:${entityId}`);\n      magasin.appliquerErreur(entityId);\n      return;\n    }\n    if (!reponse.ok) {\n      journal.push(`erreur_statut:${entityId}:${reponse.status}`);\n      magasin.appliquerErreur(entityId);\n      return;\n    }\n    const lignes = lignesValides(reponse.corps);\n    if (lignes === undefined) {\n      journal.push(`refus_forme:${entityId}`);\n      magasin.appliquerErreur(entityId);\n      return;\n    }\n    // La NOUVEAUTÉ se mesure sur les LIGNES, jamais sur la version : le\n    // cycle chargement→prêt bouge légitimement la version (transition\n    // d'état réelle et observable) même quand les données sont identiques.\n    const avant = JSON.stringify(magasin.listInstances(entityId));\n    magasin.appliquerDonnees(entityId, lignes);\n    const apres = JSON.stringify(magasin.listInstances(entityId));\n    journal.push(`donnees:${entityId}:${lignes.length}:${avant === apres ? \"identiques\" : \"nouvelles\"}`);\n  };\n\n  return {\n    demarrer: async () => {\n      for (const cible of admissibles.values()) {\n        await rafraichir(cible.entityId);\n        if (cible.refreshSeconds !== undefined && planificateur !== undefined) {\n          journal.push(`polling:${cible.entityId}:${cible.refreshSeconds}`);\n          annulations.push(planificateur(() => void rafraichir(cible.entityId), cible.refreshSeconds));\n        }\n      }\n    },\n    rafraichir,\n    arreter: () => {\n      for (const annuler of annulations.splice(0)) annuler();\n      journal.push(\"arret\");\n    },\n    journal: () => [...journal],\n  };\n}\n",
  "lib/tokens/index.ts": "// RUNTIME COPIÉ (compilateur 4.3) — point d'entrée tokens du projet\n// généré : ré-exporte le thème GÉNÉRÉ (données pures, scellé 3.1) sans\n// tirer zod ni le schéma (moteur uniquement).\nexport { theme } from \"./theme.generated\";\n",
  "lib/tokens/theme.generated.ts": "// GÉNÉRÉ par scripts/generate.mjs depuis tokens.json — NE PAS ÉDITER.\n// Thème React Native (D-021 : StyleSheet + tokens maison) — données pures,\n// aucune dépendance de bibliothèque de styling (ARCHITECTURE §22, D-021 :\n// le choix de styling ne fuite jamais dans les contrats ni dans ce module).\nexport const theme = {\n  \"color\": {\n    \"light\": {\n      \"bg\": \"#F6F7F9\",\n      \"surface\": \"#FFFFFF\",\n      \"text\": \"#16181D\",\n      \"muted\": \"#5A616E\",\n      \"primary\": \"#FA5D1E\",\n      \"onPrimary\": \"#16181D\",\n      \"border\": \"#D9DDE3\",\n      \"error\": \"#C42B1C\",\n      \"success\": \"#1F7A3D\",\n      \"warn\": \"#866A00\",\n      \"badgeBg\": \"#EEF1F5\",\n      \"primaryText\": \"#C34917\"\n    },\n    \"dark\": {\n      \"bg\": \"#0A050E\",\n      \"surface\": \"#17121C\",\n      \"text\": \"#F2F0F4\",\n      \"muted\": \"#A49FAC\",\n      \"primary\": \"#FA5D1E\",\n      \"onPrimary\": \"#16181D\",\n      \"border\": \"#2E2836\",\n      \"error\": \"#FF6B5E\",\n      \"success\": \"#4CC17A\",\n      \"warn\": \"#E3C25A\",\n      \"badgeBg\": \"#241E2B\",\n      \"primaryText\": \"#FA5D1E\"\n    }\n  },\n  \"space\": {\n    \"xxs\": 2,\n    \"xs\": 4,\n    \"sm\": 8,\n    \"md\": 12,\n    \"lg\": 16,\n    \"xl\": 24\n  },\n  \"radius\": {\n    \"sm\": 6,\n    \"md\": 10,\n    \"lg\": 16\n  },\n  \"font\": {\n    \"label\": 12,\n    \"body\": 14,\n    \"title\": 17,\n    \"heading\": 22\n  },\n  \"fontWeight\": {\n    \"semibold\": \"600\",\n    \"bold\": \"700\"\n  },\n  \"opacity\": {\n    \"disabled\": 0.5\n  },\n  \"size\": {\n    \"tapTarget\": 48\n  }\n} as const;\nexport type SchemeName = keyof typeof theme.color;\nexport type Palette = (typeof theme.color)[SchemeName];\n",
};

